# =========================
# EVENT FORMAT MIGRATION
# =========================
def ensure_event_competition_format():

    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()

    try:

        cur.execute("""
        PRAGMA table_info(events)
        """)

        event_columns = {
            row[1]
            for row in cur.fetchall()
        }

        if (
            "competition_format"
            not in event_columns
        ):

            cur.execute("""
            ALTER TABLE events
            ADD COLUMN competition_format
            TEXT NOT NULL
            DEFAULT 'Timed Finals'
            """)

        cur.execute("""
        UPDATE events
        SET competition_format = 'Timed Finals'
        WHERE competition_format IS NULL
        OR TRIM(competition_format) = ''
        """)

        conn.commit()

    finally:

        conn.close()



# =========================
# EVENT SCHEDULE MIGRATION
# FULL-DAY PROGRAMME
# =========================
def ensure_event_schedule_fields():

    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()

    try:

        cur.execute("""
        PRAGMA table_info(events)
        """)

        event_columns = {
            row[1]
            for row in cur.fetchall()
        }

        if "start_time" not in event_columns:

            cur.execute("""
            ALTER TABLE events
            ADD COLUMN start_time
            TEXT NOT NULL
            DEFAULT ''
            """)

        if (
            "heat_interval_minutes"
            not in event_columns
        ):

            cur.execute("""
            ALTER TABLE events
            ADD COLUMN heat_interval_minutes
            INTEGER NOT NULL
            DEFAULT 3
            """)

        if "final_time" not in event_columns:

            cur.execute("""
            ALTER TABLE events
            ADD COLUMN final_time
            TEXT NOT NULL
            DEFAULT ''
            """)

        cur.execute("""
        UPDATE events
        SET start_time = ''
        WHERE start_time IS NULL
        """)

        cur.execute("""
        UPDATE events
        SET heat_interval_minutes = 3
        WHERE heat_interval_minutes IS NULL
        OR heat_interval_minutes < 1
        """)

        cur.execute("""
        UPDATE events
        SET final_time = ''
        WHERE final_time IS NULL
        """)

        conn.commit()

    finally:

        conn.close()


