def ensure_programme_items_table():

    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()

    try:

        cur.execute("""
        CREATE TABLE IF NOT EXISTS programme_items
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            meeting_id INTEGER NOT NULL,
            item_key TEXT NOT NULL,
            event_id INTEGER NOT NULL,
            auto_time TEXT NOT NULL DEFAULT '',
            scheduled_time TEXT NOT NULL DEFAULT '',
            time_overridden INTEGER NOT NULL DEFAULT 0,
            sort_order INTEGER NOT NULL DEFAULT 0,
            UNIQUE(meeting_id, item_key)
        )
        """)

        cur.execute("""
        CREATE INDEX IF NOT EXISTS
        idx_programme_items_meeting_order
        ON programme_items(
            meeting_id,
            sort_order
        )
        """)

        conn.commit()

    finally:

        conn.close()


def _normalise_programme_time(value):

    value = str(value or "").strip()

    if not value:
        return ""

    try:

        parsed = datetime.strptime(
            value,
            "%H:%M"
        )

    except ValueError:
        return ""

    return parsed.strftime("%H:%M")


def _programme_time_to_minutes(value):

    value = _normalise_programme_time(
        value
    )

    if not value:
        return 99999

    parsed = datetime.strptime(
        value,
        "%H:%M"
    )

    return (
        parsed.hour * 60
        + parsed.minute
    )


def _add_programme_minutes(
    value,
    minutes
):

    value = _normalise_programme_time(
        value
    )

    if not value:
        return ""

    total = (
        _programme_time_to_minutes(value)
        + int(minutes)
    ) % (24 * 60)

    hour, minute = divmod(
        total,
        60
    )

    return f"{hour:02d}:{minute:02d}"


def build_programme_blueprint(
    meeting_id,
    conn=None
):

    """Build the programme items that currently exist.

    The item_key is deliberately based on event id plus
    stage/heat number instead of heat database ids. Heat ids
    are recreated when heats are regenerated, while Heat 1,
    Heat 2, etc. remain meaningful programme items. This lets
    manual times and order survive normal heat regeneration.
    """

    owns_connection = conn is None

    if owns_connection:
        conn = sqlite3.connect(DB_NAME)

    cur = conn.cursor()

    try:

        cur.execute("""
        SELECT
            e.id,
            e.event_name,
            e.gender,
            e.age_group,
            e.event_type,
            COALESCE(
                e.competition_format,
                'Timed Finals'
            ),
            COALESCE(
                e.start_time,
                ''
            ),
            COALESCE(
                e.heat_interval_minutes,
                3
            ),
            COALESCE(
                e.final_time,
                ''
            ),
            COUNT(
                DISTINCT CASE
                    WHEN a.id IS NOT NULL
                    THEN ee.athlete_id
                END
            )
        FROM events e

        LEFT JOIN event_entries ee
            ON ee.event_id = e.id
            AND ee.meeting_id = e.meeting_id
            AND ee.status = 'Active'

        LEFT JOIN athletes a
            ON a.id = ee.athlete_id
            AND a.status = 'Active'

        WHERE e.meeting_id = ?

        GROUP BY
            e.id,
            e.event_name,
            e.gender,
            e.age_group,
            e.event_type,
            e.competition_format,
            e.start_time,
            e.heat_interval_minutes,
            e.final_time

        HAVING COUNT(
            DISTINCT CASE
                WHEN a.id IS NOT NULL
                THEN ee.athlete_id
            END
        ) > 0

        ORDER BY e.id
        """, (
            meeting_id,
        ))

        events = cur.fetchall()
        programme_rows = []

        for event in events:

            (
                event_id,
                event_name,
                gender,
                age_group,
                event_type,
                competition_format,
                start_time,
                heat_interval_minutes,
                final_time,
                athlete_count
            ) = event

            start_time = (
                _normalise_programme_time(
                    start_time
                )
            )

            final_time = (
                _normalise_programme_time(
                    final_time
                )
            )

            try:

                interval = int(
                    heat_interval_minutes
                )

            except (
                TypeError,
                ValueError
            ):

                interval = 3

            if interval < 1:
                interval = 3

            # Record information is included in the
            # blueprint so the editor/exporter always
            # reflects the latest long-term record book.
            cur.execute("""
            SELECT
                performance,
                record_holder
            FROM athletics_records
            WHERE age_group = ?
            AND LOWER(event_name) = LOWER(?)
            AND gender = ?
            """, (
                age_group,
                event_name,
                gender
            ))

            record_row = cur.fetchone()

            record_text = ""
            record_holder = ""

            if record_row:

                record_text = str(
                    record_row[0] or ""
                ).strip()

                record_holder = str(
                    record_row[1] or ""
                ).strip()

                if (
                    record_text
                    and event_type == "High Jump"
                ):

                    try:

                        record_text = (
                            f"{float(record_text):.2f} m"
                        )

                    except ValueError:
                        pass

            def add_row(
                item_key,
                auto_time,
                stage,
                stage_order
            ):

                programme_rows.append({
                    "item_key": item_key,
                    "auto_time": auto_time,
                    "event_id": event_id,
                    "event_name": event_name,
                    "gender_age": (
                        f"{gender} {age_group}"
                    ),
                    "event_type": event_type,
                    "stage": stage,
                    "stage_order": stage_order,
                    "record": record_text,
                    "record_holder": record_holder
                })

            if event_type != "Track":

                add_row(
                    f"event:{event_id}:final",
                    start_time,
                    "Final",
                    0
                )

                continue

            cur.execute("""
            SELECT heat_number
            FROM heats
            WHERE event_id = ?
            ORDER BY heat_number
            """, (
                event_id,
            ))

            generated_heats = [
                row[0]
                for row in cur.fetchall()
            ]

            if competition_format == "Timed Finals":

                if generated_heats:
                    heat_numbers = generated_heats
                else:
                    estimated_heats = max(
                        1,
                        (
                            int(athlete_count)
                            + 7
                        ) // 8
                    )
                    heat_numbers = list(
                        range(
                            1,
                            estimated_heats + 1
                        )
                    )

                for index, heat_number in enumerate(
                    heat_numbers
                ):

                    heat_time = (
                        _add_programme_minutes(
                            start_time,
                            index * interval
                        )
                    )

                    if len(heat_numbers) > 1:
                        stage = (
                            "Timed Final - "
                            f"Heat {heat_number}"
                        )
                    else:
                        stage = "Timed Final"

                    add_row(
                        (
                            f"event:{event_id}:"
                            f"timed_heat:{heat_number}"
                        ),
                        heat_time,
                        stage,
                        index
                    )

            else:

                if int(athlete_count) <= 8:

                    add_row(
                        f"event:{event_id}:final",
                        final_time,
                        "Final",
                        1000
                    )

                else:

                    if generated_heats:
                        heat_numbers = generated_heats
                    else:
                        estimated_heats = (
                            (
                                int(athlete_count)
                                + 7
                            ) // 8
                        )
                        heat_numbers = list(
                            range(
                                1,
                                estimated_heats + 1
                            )
                        )

                    for index, heat_number in enumerate(
                        heat_numbers
                    ):

                        heat_time = (
                            _add_programme_minutes(
                                start_time,
                                index * interval
                            )
                        )

                        add_row(
                            (
                                f"event:{event_id}:"
                                f"heat:{heat_number}"
                            ),
                            heat_time,
                            f"Heat {heat_number}",
                            index
                        )

                    add_row(
                        f"event:{event_id}:final",
                        final_time,
                        "Final",
                        1000
                    )

        programme_rows.sort(
            key=lambda row: (
                _programme_time_to_minutes(
                    row["auto_time"]
                ),
                row["event_id"],
                row["stage_order"]
            )
        )

        return programme_rows

    finally:

        if owns_connection:
            conn.close()


def sync_programme_schedule(
    meeting_id,
    conn=None
):

    """Synchronise generated heats/finals with manual programme edits.

    Existing item times and order are preserved. Newly generated heats
    are inserted beside their sibling heats. Obsolete heat rows are
    removed automatically after regeneration.
    """

    owns_connection = conn is None

    if owns_connection:
        conn = sqlite3.connect(DB_NAME)

    cur = conn.cursor()

    try:

        blueprint = build_programme_blueprint(
            meeting_id,
            conn
        )

        blueprint_by_key = {
            row["item_key"]: row
            for row in blueprint
        }

        blueprint_keys = [
            row["item_key"]
            for row in blueprint
        ]

        cur.execute("""
        SELECT
            item_key,
            scheduled_time,
            auto_time,
            time_overridden,
            sort_order
        FROM programme_items
        WHERE meeting_id = ?
        ORDER BY
            sort_order,
            id
        """, (
            meeting_id,
        ))

        existing_rows = cur.fetchall()

        existing = {
            row[0]: {
                "scheduled_time": row[1] or "",
                "auto_time": row[2] or "",
                "time_overridden": int(
                    row[3] or 0
                ),
                "sort_order": int(
                    row[4] or 0
                )
            }
            for row in existing_rows
        }

        current_keys = set(
            blueprint_keys
        )

        # Remove rows that no longer exist after athlete
        # withdrawals or heat regeneration.
        stale_keys = [
            key
            for key in existing
            if key not in current_keys
        ]

        for item_key in stale_keys:

            cur.execute("""
            DELETE FROM programme_items
            WHERE meeting_id = ?
            AND item_key = ?
            """, (
                meeting_id,
                item_key
            ))

            existing.pop(
                item_key,
                None
            )

        # Keep existing manually edited times. Items that
        # still follow their default time automatically move
        # when the event's base time/interval is changed.
        for row in blueprint:

            item_key = row["item_key"]
            auto_time = row["auto_time"]

            if item_key in existing:

                old = existing[item_key]

                if old["time_overridden"]:
                    scheduled_time = (
                        old["scheduled_time"]
                    )
                    time_overridden = 1
                else:
                    scheduled_time = auto_time
                    time_overridden = 0

                cur.execute("""
                UPDATE programme_items
                SET
                    event_id = ?,
                    auto_time = ?,
                    scheduled_time = ?,
                    time_overridden = ?
                WHERE meeting_id = ?
                AND item_key = ?
                """, (
                    row["event_id"],
                    auto_time,
                    scheduled_time,
                    time_overridden,
                    meeting_id,
                    item_key
                ))

            else:

                cur.execute("""
                INSERT INTO programme_items
                (
                    meeting_id,
                    item_key,
                    event_id,
                    auto_time,
                    scheduled_time,
                    time_overridden,
                    sort_order
                )
                VALUES (?, ?, ?, ?, ?, 0, 999999)
                """, (
                    meeting_id,
                    item_key,
                    row["event_id"],
                    auto_time,
                    auto_time
                ))

        # Start with the user's saved manual order.
        ordered_keys = [
            row[0]
            for row in existing_rows
            if row[0] in current_keys
        ]

        # Add each new programme item beside its nearest
        # automatic predecessor/successor. For example a new
        # Heat 3 naturally appears after Heat 2, without
        # disturbing unrelated manual programme ordering.
        for index, item_key in enumerate(
            blueprint_keys
        ):

            if item_key in ordered_keys:
                continue

            previous_key = None

            for candidate in reversed(
                blueprint_keys[:index]
            ):

                if candidate in ordered_keys:
                    previous_key = candidate
                    break

            if previous_key is not None:

                insert_at = (
                    ordered_keys.index(
                        previous_key
                    )
                    + 1
                )

                ordered_keys.insert(
                    insert_at,
                    item_key
                )

                continue

            next_key = None

            for candidate in blueprint_keys[
                index + 1:
            ]:

                if candidate in ordered_keys:
                    next_key = candidate
                    break

            if next_key is not None:

                ordered_keys.insert(
                    ordered_keys.index(
                        next_key
                    ),
                    item_key
                )

            else:

                ordered_keys.append(
                    item_key
                )

        # Normalise sort values so repeated Up/Down edits
        # remain simple and stable.
        for index, item_key in enumerate(
            ordered_keys,
            start=1
        ):

            cur.execute("""
            UPDATE programme_items
            SET sort_order = ?
            WHERE meeting_id = ?
            AND item_key = ?
            """, (
                index * 10,
                meeting_id,
                item_key
            ))

        conn.commit()

        cur.execute("""
        SELECT
            item_key,
            scheduled_time,
            auto_time,
            time_overridden,
            sort_order
        FROM programme_items
        WHERE meeting_id = ?
        ORDER BY
            sort_order,
            id
        """, (
            meeting_id,
        ))

        saved_rows = {
            row[0]: {
                "scheduled_time": row[1] or "",
                "auto_time": row[2] or "",
                "time_overridden": int(
                    row[3] or 0
                ),
                "sort_order": int(
                    row[4] or 0
                )
            }
            for row in cur.fetchall()
        }

        merged_rows = []

        for item_key in ordered_keys:

            blueprint_row = (
                blueprint_by_key.get(
                    item_key
                )
            )

            saved = saved_rows.get(
                item_key
            )

            if not blueprint_row or not saved:
                continue

            merged = dict(
                blueprint_row
            )

            merged["time"] = (
                saved["scheduled_time"]
            )

            merged["time_minutes"] = (
                _programme_time_to_minutes(
                    merged["time"]
                )
            )

            merged["sort_order"] = (
                saved["sort_order"]
            )

            merged["time_overridden"] = (
                saved["time_overridden"]
            )

            merged_rows.append(
                merged
            )

        return merged_rows

    finally:

        if owns_connection:
            conn.close()


# =========================
# ATHLETICS RECORDS
# GLOBAL / MULTI-YEAR STORAGE
# =========================
def ensure_records_table():

    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()

    try:

        # Records intentionally do NOT contain a
        # meeting_id. They are the long-term record
        # book shared across all meetings and years.
        cur.execute("""
        CREATE TABLE IF NOT EXISTS athletics_records
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            age_group TEXT NOT NULL,
            event_name TEXT NOT NULL,
            gender TEXT NOT NULL,
            event_type TEXT NOT NULL,
            performance TEXT,
            record_holder TEXT,
            record_year TEXT,
            updated_at TEXT NOT NULL
                DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(
                age_group,
                event_name,
                gender
            )
        )
        """)

        conn.commit()

    finally:

        conn.close()


def get_athletics_record(
    age_group,
    event_name,
    gender
):

    """Return the exact record for an event.

    The printable officials programme can use this
    helper later so the correct age/gender/event
    record is printed on the official's page.
    """

    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()

    try:

        cur.execute("""
        SELECT
            event_type,
            performance,
            record_holder,
            record_year,
            updated_at
        FROM athletics_records
        WHERE age_group = ?
        AND LOWER(event_name) = LOWER(?)
        AND gender = ?
        """, (
            age_group,
            event_name,
            gender
        ))

        row = cur.fetchone()

        if not row:
            return None

        return {
            "event_type": row[0],
            "performance": row[1] or "",
            "record_holder": row[2] or "",
            "record_year": row[3] or "",
            "updated_at": row[4] or ""
        }

    finally:

        conn.close()


# =========================
# TIMED FINAL RECALCULATION
# TRACK EVENTS
# =========================
def rebuild_timed_final_results(
    event_id
):

    conn = sqlite3.connect(DB_NAME)
    cur = conn.cursor()

    try:

        cur.execute("""
        SELECT
            meeting_id,
            event_type,
            COALESCE(
                competition_format,
                'Timed Finals'
            )
        FROM events
        WHERE id = ?
        """, (
            event_id,
        ))

        event = cur.fetchone()

        if not event:

            return {
                "complete": False,
                "expected": 0,
                "recorded": 0,
                "ranked": 0
            }

        meeting_id = event[0]
        event_type = event[1]
        competition_format = event[2]

        if (
            event_type != "Track"
            or competition_format
            != "Timed Finals"
        ):

            return {
                "complete": False,
                "expected": 0,
                "recorded": 0,
                "ranked": 0
            }

        # Every active event entry is expected
        # to have one recorded Timed Final result.
        cur.execute("""
        SELECT
            ee.athlete_id,
            a.team_id
        FROM event_entries ee

        JOIN athletes a
            ON ee.athlete_id = a.id

        WHERE ee.event_id = ?
        AND ee.meeting_id = ?
        AND ee.status = 'Active'
        AND a.status = 'Active'

        ORDER BY ee.athlete_id
        """, (
            event_id,
            meeting_id
        ))

        expected_rows = (
            cur.fetchall()
        )

        expected_ids = {
            row[0]
            for row in expected_rows
        }

        team_by_athlete = {
            row[0]: row[1]
            for row in expected_rows
        }

        expected_count = len(
            expected_ids
        )

        # Reset the displayed position for every
        # result belonging to this event. In Timed
        # Finals, Position means OVERALL position,
        # not position inside one heat.
        cur.execute("""
        UPDATE results
        SET position = NULL
        WHERE heat_id IN (
            SELECT id
            FROM heats
            WHERE event_id = ?
        )
        """, (
            event_id,
        ))

        # Rebuild the official event results from
        # all generated heats.
        cur.execute("""
        DELETE FROM final_results
        WHERE event_id = ?
        """, (
            event_id,
        ))

        cur.execute("""
        DELETE FROM awarded_points
        WHERE event_id = ?
        """, (
            event_id,
        ))

        cur.execute("""
        SELECT
            r.athlete_id,
            r.performance,
            he.lane_number,
            r.heat_id
        FROM results r

        JOIN heats h
            ON r.heat_id = h.id

        LEFT JOIN heat_entries he
            ON he.heat_id = r.heat_id
            AND he.athlete_id = r.athlete_id

        WHERE h.event_id = ?
        """, (
            event_id,
        ))

        recorded_results = []

        for (
            athlete_id,
            performance,
            lane_number,
            heat_id
        ) in cur.fetchall():

            if athlete_id not in expected_ids:
                continue

            if performance is None:
                continue

            performance_text = (
                str(performance).strip()
            )

            if not performance_text:
                continue

            recorded_results.append(
                (
                    athlete_id,
                    performance_text,
                    lane_number or 0,
                    heat_id
                )
            )

        # One result per athlete is expected.
        # If an accidental duplicate heat assignment
        # exists, keep the first result only so the
        # error cannot create duplicate official rows.
        unique_recorded = {}

        for result_row in recorded_results:

            athlete_id = result_row[0]

            if (
                athlete_id
                not in unique_recorded
            ):
                unique_recorded[
                    athlete_id
                ] = result_row

        recorded_results = list(
            unique_recorded.values()
        )

        recorded_count = len(
            recorded_results
        )

        numeric_results = []

        for (
            athlete_id,
            performance_text,
            lane_number,
            heat_id
        ) in recorded_results:

            try:

                value = float(
                    performance_text
                )

                numeric_results.append(
                    (
                        athlete_id,
                        value,
                        performance_text,
                        lane_number,
                        heat_id
                    )
                )

            except (
                ValueError,
                TypeError
            ):

                # DNS / DNF / DQ are valid recorded
                # outcomes but do not receive a place.
                pass

        numeric_results.sort(
            key=lambda row: row[1]
        )

        positions = {}

        previous_value = None
        previous_position = None

        for index, result_row in enumerate(
            numeric_results,
            start=1
        ):

            athlete_id = result_row[0]
            value = result_row[1]

            if (
                previous_value is not None
                and value == previous_value
            ):

                position = (
                    previous_position
                )

            else:

                # Competition ranking:
                # 1, 2, 2, 4
                position = index

            positions[
                athlete_id
            ] = position

            previous_value = value
            previous_position = position

        # Store the OVERALL Timed Final position
        # back on every heat result.
        for (
            athlete_id,
            performance_text,
            lane_number,
            heat_id
        ) in recorded_results:

            cur.execute("""
            UPDATE results
            SET position = ?
            WHERE heat_id = ?
            AND athlete_id = ?
            """, (
                positions.get(
                    athlete_id
                ),
                heat_id,
                athlete_id
            ))

            cur.execute("""
            INSERT INTO final_results
            (
                event_id,
                athlete_id,
                lane_number,
                performance,
                position
            )
            VALUES (?, ?, ?, ?, ?)

            ON CONFLICT(
                event_id,
                athlete_id
            )
            DO UPDATE SET
                lane_number =
                    excluded.lane_number,
                performance =
                    excluded.performance,
                position =
                    excluded.position
            """, (
                event_id,
                athlete_id,
                lane_number,
                performance_text,
                positions.get(
                    athlete_id
                )
            ))

        complete = (
            expected_count > 0
            and recorded_count
            == expected_count
        )

        # Points become official only once every
        # active athlete has a recorded result.
        if complete:

            for (
                athlete_id,
                position
            ) in positions.items():

                cur.execute("""
                SELECT points
                FROM points_config
                WHERE meeting_id = ?
                AND position = ?
                """, (
                    meeting_id,
                    position
                ))

                points_row = (
                    cur.fetchone()
                )

                if not points_row:
                    continue

                points = (
                    points_row[0]
                )

                cur.execute("""
                INSERT INTO awarded_points
                (
                    meeting_id,
                    event_id,
                    athlete_id,
                    team_id,
                    position,
                    points
                )
                VALUES (?, ?, ?, ?, ?, ?)

                ON CONFLICT(
                    event_id,
                    athlete_id
                )
                DO UPDATE SET
                    team_id =
                        excluded.team_id,
                    position =
                        excluded.position,
                    points =
                        excluded.points
                """, (
                    meeting_id,
                    event_id,
                    athlete_id,
                    team_by_athlete.get(
                        athlete_id
                    ),
                    position,
                    points
                ))

        conn.commit()

        return {
            "complete": complete,
            "expected": expected_count,
            "recorded": recorded_count,
            "ranked": len(
                numeric_results
            )
        }

    except Exception:

        conn.rollback()
        raise

    finally:

        conn.close()


# =========================
# RESOURCE PATH
# =========================
def resource_path(relative_path):

    # When packaged as an EXE,
    # PyInstaller extracts bundled files
    # into a temporary folder.
    if hasattr(sys, "_MEIPASS"):

        base_path = sys._MEIPASS

    else:

        base_path = os.path.dirname(
            os.path.abspath(__file__)
        )

    return os.path.join(
        base_path,
        relative_path
    )


