        "border-radius: 8px;"
        "font-size: 14px;"
        "font-weight: 700;"
        "padding: 8px 16px;"
        "}"
        "QPushButton:hover { opacity: 0.92; }"
        "QPushButton:pressed { padding-top: 9px; }"
