def _apply_modern_screen_theme(root, accent="#1E5CC8"):
    root.setStyleSheet(
        "QWidget { color: #102F5E; }"
        "QLineEdit, QComboBox, QDateEdit {"
        "background: white;"
        "border: 1px solid #C9D6E5;"
        "border-radius: 8px;"
        "padding: 8px 10px;"
        "min-height: 34px;"
        "font-size: 13px;"
        "}"
        "QLineEdit:focus, QComboBox:focus, QDateEdit:focus {"
        f"border: 1px solid {accent};"
        "}"
        "QListWidget, QTableWidget {"
        "background: white;"
        "border: 1px solid #D7E1ED;"
        "border-radius: 9px;"
        "gridline-color: #E2E8F0;"
        "font-size: 13px;"
        "}"
        "QListWidget::item { padding: 8px; border-bottom: 1px solid #EDF1F6; }"
        "QListWidget::item:selected {"
        f"background: {accent}; color: white; border-radius: 5px;"
        "}"
        "QHeaderView::section {"
        "background: #F1F5FA;"
        "color: #183965;"
        "border: none;"
        "border-bottom: 1px solid #D6E0EB;"
        "padding: 10px;"
        "font-weight: 700;"
        "font-size: 13px;"
        "}"
        "QTabWidget::pane {"
        "border: 1px solid #D7E1ED; border-radius: 10px; background: white;"
        "}"
        "QTabBar::tab {"
        "background: #F1F5FA; color: #143767; padding: 9px 18px; margin-right: 2px;"
        "border-top-left-radius: 7px; border-top-right-radius: 7px;"
        "}"
        "QTabBar::tab:selected {"
        f"background: {accent}; color: white;"
        "}"
    )

    for table in root.findChildren(QTableWidget):
        table.setAlternatingRowColors(True)
        table.verticalHeader().setVisible(False)
        table.horizontalHeader().setStretchLastSection(True)
        table.setStyleSheet(
            table.styleSheet() +
            "QTableWidget { alternate-background-color: #F8FAFD; }"
        )

