    def add_team(self):

        meeting_id = get_active_meeting()

        if not meeting_id:

            QMessageBox.warning(
                self,
                "No Active Meeting",
                "Select an active meeting first."
            )

            return

        name = self.team_name.text().strip()

        if not name:

            QMessageBox.warning(
                self,
                "Missing Name",
                "Enter a team or house name."
            )

            return

        team_type = (
            self.team_type.currentText()
        )

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # Prevent duplicate team names
        # inside the same meeting
        cur.execute("""
        SELECT id
        FROM teams
        WHERE meeting_id = ?
        AND LOWER(name) = LOWER(?)
        """, (
            meeting_id,
            name
        ))

        if cur.fetchone():

            conn.close()

            QMessageBox.warning(
                self,
                "Duplicate Team",
                (
                    "A team or house with this "
                    "name already exists."
                )
            )

            return

        cur.execute("""
        INSERT INTO teams
        (
            meeting_id,
            name,
            team_type
        )
        VALUES (?, ?, ?)
        """, (
            meeting_id,
            name,
            team_type
        ))

        conn.commit()
        conn.close()

        QMessageBox.information(
            self,
            "Team Added",
            "Team or house added successfully."
        )

        self.clear_selection()
        self.load_teams()


    # =========================
    # LOAD TEAMS
    # =========================
    def load_teams(self):

        self.team_list.clear()

        meeting_id = get_active_meeting()

        if not meeting_id:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        cur.execute("""
        SELECT
            id,
            name,
            team_type
        FROM teams
        WHERE meeting_id = ?
        ORDER BY name
        """, (meeting_id,))

        rows = cur.fetchall()

        conn.close()

        for (
            team_id,
            name,
            team_type
        ) in rows:

            item = QListWidgetItem(
                f"{name} ({team_type})"
            )

            item.setData(
                Qt.UserRole,
                team_id
            )

            self.team_list.addItem(
                item
            )


    # =========================
    # LOAD SELECTED TEAM
    # =========================
    def load_selected_team(
        self,
        item
    ):

        team_id = item.data(
            Qt.UserRole
        )

        if not team_id:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        cur.execute("""
        SELECT
            name,
            team_type
        FROM teams
        WHERE id = ?
        """, (team_id,))

        team = cur.fetchone()

        conn.close()

        if not team:
            return

        self.selected_team_id = team_id

        name = team[0]
        team_type = team[1]

        self.team_name.setText(
            name
        )

        type_index = (
            self.team_type.findText(
                team_type
            )
        )

        if type_index >= 0:

            self.team_type.setCurrentIndex(
                type_index
            )


    # =========================
    # UPDATE TEAM
    # =========================
    def update_team(self):

        if not self.selected_team_id:

            QMessageBox.warning(
                self,
                "No Team Selected",
                (
                    "Select a team or house "
                    "from the list first."
                )
            )

            return

        name = self.team_name.text().strip()

        if not name:

            QMessageBox.warning(
                self,
                "Missing Name",
                "Enter a team or house name."
            )

            return

        meeting_id = get_active_meeting()

        team_type = (
            self.team_type.currentText()
        )

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # Make sure another team does
        # not already use this name.
        cur.execute("""
        SELECT id
        FROM teams
        WHERE meeting_id = ?
        AND LOWER(name) = LOWER(?)
        AND id != ?
        """, (
            meeting_id,
            name,
            self.selected_team_id
        ))

        if cur.fetchone():

            conn.close()

            QMessageBox.warning(
                self,
                "Duplicate Team",
                (
                    "Another team or house "
                    "already uses this name."
                )
            )

            return

        cur.execute("""
        UPDATE teams
        SET
            name = ?,
            team_type = ?
        WHERE id = ?
        """, (
            name,
            team_type,
            self.selected_team_id
        ))

        conn.commit()
        conn.close()

        QMessageBox.information(
            self,
            "Team Updated",
            "Team or house updated successfully."
        )

        self.clear_selection()
        self.load_teams()


    # =========================
    # DELETE TEAM
    # =========================
    def delete_team(self):

        if not self.selected_team_id:

            QMessageBox.warning(
                self,
                "No Team Selected",
                (
                    "Select a team or house "
                    "from the list first."
                )
            )

            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # Check whether athletes
        # are still assigned to it.
        cur.execute("""
        SELECT COUNT(*)
        FROM athletes
        WHERE team_id = ?
        """, (
            self.selected_team_id,
        ))

        athlete_count = cur.fetchone()[0]

        if athlete_count > 0:

            conn.close()

            QMessageBox.warning(
                self,
                "Team Cannot Be Deleted",
                (
                    f"{athlete_count} athlete(s) "
                    "are still assigned to this "
                    "team or house.\n\n"
                    "Move or delete those athletes "
                    "before deleting the team."
                )
            )

            return

        name = self.team_name.text().strip()

        answer = QMessageBox.question(
            self,
            "Delete Team",
            (
                f"Are you sure you want to "
                f"delete {name}?"
            ),
            QMessageBox.Yes
            | QMessageBox.No
        )

        if answer != QMessageBox.Yes:

            conn.close()
            return

        cur.execute("""
        DELETE FROM teams
        WHERE id = ?
        """, (
            self.selected_team_id,
        ))

        conn.commit()
        conn.close()

        QMessageBox.information(
            self,
            "Team Deleted",
            "Team or house deleted successfully."
        )

        self.clear_selection()
        self.load_teams()


    # =========================
    # CLEAR SELECTION
    # =========================
    def clear_selection(self):

        self.selected_team_id = None

        self.team_list.clearSelection()

        self.team_name.clear()

        if self.team_type.count() > 0:

            self.team_type.setCurrentIndex(0)

