    def update_format_availability(
        self
    ):

        event_type = (
            self.event_type.currentText()
        )

        if event_type == "Track":

            self.format_combo.setEnabled(
                True
            )

            self.heat_interval.setEnabled(
                True
            )

            is_normal = (
                self.format_combo.currentText()
                == "Normal Heats + Final"
            )

            self.final_time.setEnabled(
                is_normal
            )

            if not is_normal:
                self.final_time.clear()

        else:

            timed_index = (
                self.format_combo.findText(
                    "Timed Finals"
                )
            )

            if timed_index >= 0:

                self.format_combo.setCurrentIndex(
                    timed_index
                )

            self.format_combo.setEnabled(
                False
            )

            self.heat_interval.setEnabled(
                False
            )

            self.final_time.setEnabled(
                False
            )

            self.final_time.clear()


    def read_schedule_fields(
        self,
        event_type,
        competition_format
    ):

        start_time = (
            self.start_time.text().strip()
        )

        if not start_time:

            raise ValueError(
                "Enter a scheduled start time "
                "for the event."
            )

        try:

            parsed_start = datetime.strptime(
                start_time,
                "%H:%M"
            )

        except ValueError as error:

            raise ValueError(
                "Scheduled Start Time must use "
                "24-hour HH:MM format, for example 08:30."
            ) from error

        start_time = parsed_start.strftime(
            "%H:%M"
        )

        heat_interval_minutes = 3
        final_time = ""

        if event_type == "Track":

            interval_text = (
                self.heat_interval.text().strip()
            )

            if not interval_text:

                interval_text = "3"

            try:

                heat_interval_minutes = int(
                    interval_text
                )

            except ValueError as error:

                raise ValueError(
                    "Minutes Between Track Heats "
                    "must be a whole number."
                ) from error

            if not (
                1 <= heat_interval_minutes <= 60
            ):

                raise ValueError(
                    "Minutes Between Track Heats "
                    "must be between 1 and 60."
                )

            if (
                competition_format
                == "Normal Heats + Final"
            ):

                final_time = (
                    self.final_time.text().strip()
                )

                if not final_time:

                    raise ValueError(
                        "Enter the scheduled Final Time "
                        "for a Normal Heats + Final event."
                    )

                try:

                    parsed_final = (
                        datetime.strptime(
                            final_time,
                            "%H:%M"
                        )
                    )

                except ValueError as error:

                    raise ValueError(
                        "Scheduled Final Time must use "
                        "24-hour HH:MM format, "
                        "for example 12:30."
                    ) from error

                final_time = (
                    parsed_final.strftime(
                        "%H:%M"
                    )
                )

        return (
            start_time,
            heat_interval_minutes,
            final_time
        )


    # =========================
    # ADD EVENT
    # =========================
    def save_event(self):

        meeting_id = get_active_meeting()

        if not meeting_id:

            QMessageBox.warning(
                self,
                "No Active Meeting",
                "Select an active meeting first."
            )

            return

        name = self.event_name.text().strip()

        if not name:

            QMessageBox.warning(
                self,
                "Missing Event Name",
                "Enter an event name."
            )

            return

        event_type = (
            self.event_type.currentText()
        )

        competition_format = (
            self.format_combo.currentText()
        )

        if event_type != "Track":

            competition_format = (
                "Timed Finals"
            )

        gender = (
            self.gender_combo.currentText()
        )

        age_group = (
            self.age_combo.currentText()
        )

        try:

            (
                start_time,
                heat_interval_minutes,
                final_time
            ) = self.read_schedule_fields(
                event_type,
                competition_format
            )

        except ValueError as error:

            QMessageBox.warning(
                self,
                "Invalid Event Schedule",
                str(error)
            )

            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # Prevent duplicate events
        cur.execute("""
        SELECT id
        FROM events
        WHERE meeting_id = ?
        AND LOWER(event_name) = LOWER(?)
        AND gender = ?
        AND age_group = ?
        """, (
            meeting_id,
            name,
            gender,
            age_group
        ))

        if cur.fetchone():

            conn.close()

            QMessageBox.warning(
                self,
                "Duplicate Event",
                (
                    "This event already exists "
                    "for this gender and age group."
                )
            )

            return

        cur.execute("""
        INSERT INTO events
        (
            meeting_id,
            event_name,
            event_type,
            gender,
            age_group,
            competition_format,
            start_time,
            heat_interval_minutes,
            final_time
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            meeting_id,
            name,
            event_type,
            gender,
            age_group,
            competition_format,
            start_time,
            heat_interval_minutes,
            final_time
        ))

        conn.commit()
        conn.close()

        QMessageBox.information(
            self,
            "Event Added",
            "Event added successfully."
        )

        self.clear_selection()
        self.load_events()


    # =========================
    # LOAD EVENTS
    # =========================
    def load_events(self):

        self.event_list.clear()

        meeting_id = get_active_meeting()

        if not meeting_id:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        cur.execute("""
        SELECT
            id,
            event_name,
            gender,
            age_group,
            event_type,
            COALESCE(
                competition_format,
                'Timed Finals'
            ),
            COALESCE(
                start_time,
                ''
            )
        FROM events
        WHERE meeting_id = ?
        ORDER BY
            CASE
                WHEN TRIM(
                    COALESCE(
                        start_time,
                        ''
                    )
                ) = ''
                THEN 1
                ELSE 0
            END,
            start_time,
            event_name,
            gender,
            age_group
        """, (meeting_id,))

        rows = cur.fetchall()

        conn.close()

        for (
            event_id,
            name,
            gender,
            age_group,
            event_type,
            competition_format,
            start_time
        ) in rows:

            time_text = (
                start_time
                if start_time
                else "UNSCHEDULED"
            )

            item = QListWidgetItem(
                f"[{time_text}] "
                f"{name} "
                f"({gender} {age_group}) "
                f"- {event_type} | "
                f"{competition_format}"
            )

            item.setData(
                Qt.UserRole,
                event_id
            )

            self.event_list.addItem(
                item
            )


    # =========================
    # LOAD SELECTED EVENT
    # =========================
    def load_selected_event(
        self,
        item
    ):

        event_id = item.data(
            Qt.UserRole
        )

        if not event_id:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        cur.execute("""
        SELECT
            event_name,
            event_type,
            gender,
            age_group,
            COALESCE(
                competition_format,
                'Timed Finals'
            ),
            COALESCE(
                start_time,
                ''
            ),
            COALESCE(
                heat_interval_minutes,
                3
            ),
            COALESCE(
                final_time,
                ''
            )
        FROM events
        WHERE id = ?
        """, (event_id,))

        event = cur.fetchone()

        conn.close()

        if not event:
            return

        name = event[0]
        event_type = event[1]
        gender = event[2]
        age_group = event[3]
        competition_format = event[4]
        start_time = event[5]
        heat_interval_minutes = event[6]
        final_time = event[7]

        self.selected_event_id = (
            event_id
        )

        self.event_name.setText(
            name
        )

        gender_index = (
            self.gender_combo.findText(
                gender
            )
        )

        if gender_index >= 0:

            self.gender_combo.setCurrentIndex(
                gender_index
            )

        age_index = (
            self.age_combo.findText(
                age_group
            )
        )

        if age_index >= 0:

            self.age_combo.setCurrentIndex(
                age_index
            )

        type_index = (
            self.event_type.findText(
                event_type
            )
        )

        if type_index >= 0:

            self.event_type.setCurrentIndex(
                type_index
            )

        format_index = (
            self.format_combo.findText(
                competition_format
            )
        )

        if format_index >= 0:

            self.format_combo.setCurrentIndex(
                format_index
            )

        self.start_time.setText(
            start_time
        )

        self.heat_interval.setText(
            str(
                heat_interval_minutes
                if heat_interval_minutes
                else 3
            )
        )

        self.final_time.setText(
            final_time
        )

        self.update_format_availability()

        # update_format_availability clears final_time
        # for formats that do not use it. Restore the
        # saved value only when this event actually uses
        # Normal Heats + Final.
        if (
            event_type == "Track"
            and competition_format
            == "Normal Heats + Final"
        ):

            self.final_time.setText(
                final_time
            )


    # =========================
    # UPDATE EVENT
    # =========================
    def update_event(self):

        if not self.selected_event_id:

            QMessageBox.warning(
                self,
                "No Event Selected",
                "Select an event from the list first."
            )

            return

        meeting_id = get_active_meeting()

        if not meeting_id:
            return

        name = self.event_name.text().strip()

        if not name:

            QMessageBox.warning(
                self,
                "Missing Event Name",
                "Enter an event name."
            )

            return

        event_type = (
            self.event_type.currentText()
        )

        competition_format = (
            self.format_combo.currentText()
        )

        # Field and High Jump currently use their
        # specialised Timed Final result systems.
        if event_type != "Track":

            competition_format = (
                "Timed Finals"
            )

        gender = (
            self.gender_combo.currentText()
        )

        age_group = (
            self.age_combo.currentText()
        )

        try:

            (
                start_time,
                heat_interval_minutes,
                final_time
            ) = self.read_schedule_fields(
                event_type,
                competition_format
            )

        except ValueError as error:

            QMessageBox.warning(
                self,
                "Invalid Event Schedule",
                str(error)
            )

            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # Get current event details
        cur.execute("""
        SELECT
            event_name,
            event_type,
            gender,
            age_group,
            COALESCE(
                competition_format,
                'Timed Finals'
            )
        FROM events
        WHERE id = ?
        """, (
            self.selected_event_id,
        ))

        previous = cur.fetchone()

        if not previous:

            conn.close()
            return

        old_name = previous[0]
        old_event_type = previous[1]
        old_gender = previous[2]
        old_age_group = previous[3]
        old_competition_format = (
            previous[4]
        )

        # Check for duplicate event
        cur.execute("""
        SELECT id
        FROM events
        WHERE meeting_id = ?
        AND LOWER(event_name) = LOWER(?)
        AND gender = ?
        AND age_group = ?
        AND id != ?
        """, (
            meeting_id,
            name,
            gender,
            age_group,
            self.selected_event_id
        ))

        if cur.fetchone():

            conn.close()

            QMessageBox.warning(
                self,
                "Duplicate Event",
                (
                    "Another event already exists "
                    "with this name, gender "
                    "and age group."
                )
            )

            return

        # Changing only the name is safe.
        core_structure_changed = (
            event_type
            != old_event_type
            or gender
            != old_gender
            or age_group
            != old_age_group
        )

        format_changed = (
            competition_format
            != old_competition_format
        )

        competition_structure_changed = (
            core_structure_changed
            or format_changed
        )

        if competition_structure_changed:

            if core_structure_changed:

                change_description = (
                    "You changed the event's gender, "
                    "age group or event type."
                )

            else:

                change_description = (
                    "You changed the competition "
                    "format."
                )

            answer = QMessageBox.question(
                self,
                "Event Structure Changed",
                (
                    f"{change_description}\n\n"
                    "Existing generated heats, results, "
                    "finals and points for this event "
                    "must be cleared.\n\n"
                    "The athlete event entries will be "
                    + (
                        "cleared because the event's "
                        "core structure changed."
                        if core_structure_changed
                        else "kept because only the "
                             "competition format changed."
                    )
                    + "\n\nContinue?"
                ),
                QMessageBox.Yes
                | QMessageBox.No
            )

            if answer != QMessageBox.Yes:

                conn.close()
                return

            event_id = (
                self.selected_event_id
            )

            # Remove points
            cur.execute("""
            DELETE FROM awarded_points
            WHERE event_id = ?
            """, (event_id,))

            # Remove final results
            cur.execute("""
            DELETE FROM final_results
            WHERE event_id = ?
            """, (event_id,))

            # Remove measured field attempts
            cur.execute("""
            DELETE FROM field_attempts
            WHERE event_id = ?
            """, (event_id,))

            # Remove High Jump attempts
            cur.execute("""
            DELETE FROM high_jump_attempts
            WHERE event_id = ?
            """, (event_id,))

            # Remove High Jump heights
            cur.execute("""
            DELETE FROM high_jump_heights
            WHERE event_id = ?
            """, (event_id,))

            # Remove finalists
            cur.execute("""
            DELETE FROM finals
            WHERE event_id = ?
            """, (event_id,))

            # Remove heat results
            cur.execute("""
            DELETE FROM results
            WHERE heat_id IN (
                SELECT id
                FROM heats
                WHERE event_id = ?
            )
            """, (event_id,))

            # Remove heat entries
            cur.execute("""
            DELETE FROM heat_entries
            WHERE heat_id IN (
                SELECT id
                FROM heats
                WHERE event_id = ?
            )
            """, (event_id,))

            # Remove heats
            cur.execute("""
            DELETE FROM heats
            WHERE event_id = ?
            """, (event_id,))

            # Gender, age group or event type
            # changes can invalidate entries.
            # A format-only change keeps them.
            if core_structure_changed:

                cur.execute("""
                DELETE FROM event_entries
                WHERE event_id = ?
                """, (event_id,))

        cur.execute("""
        UPDATE events
        SET
            event_name = ?,
            event_type = ?,
            gender = ?,
            age_group = ?,
            competition_format = ?,
            start_time = ?,
            heat_interval_minutes = ?,
            final_time = ?
        WHERE id = ?
        """, (
            name,
            event_type,
            gender,
            age_group,
            competition_format,
            start_time,
            heat_interval_minutes,
            final_time,
            self.selected_event_id
        ))

        conn.commit()
        conn.close()

        QMessageBox.information(
            self,
            "Event Updated",
            "Event updated successfully."
        )

        self.clear_selection()
        self.load_events()


    def delete_event(self):

        if not self.selected_event_id:

            QMessageBox.warning(
                self,
                "No Event Selected",
                "Select an event from the list first."
            )

            return

        name = self.event_name.text().strip()

        gender = (
            self.gender_combo.currentText()
        )

        age_group = (
            self.age_combo.currentText()
        )

        answer = QMessageBox.question(
            self,
            "Delete Event",
            (
                f"Are you sure you want to delete:\n\n"
                f"{name} ({gender} {age_group})?\n\n"
                "All entries, heats, results, finals "
                "and points for this event will also "
                "be permanently deleted."
            ),
            QMessageBox.Yes
            | QMessageBox.No
        )

        if answer != QMessageBox.Yes:
            return

        event_id = (
            self.selected_event_id
        )

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # Remove awarded points
        cur.execute("""
        DELETE FROM awarded_points
        WHERE event_id = ?
        """, (event_id,))

        # Remove final results
        cur.execute("""
        DELETE FROM final_results
        WHERE event_id = ?
        """, (event_id,))

        # Remove measured field attempts
        cur.execute("""
        DELETE FROM field_attempts
        WHERE event_id = ?
        """, (event_id,))

        # Remove High Jump attempts
        cur.execute("""
        DELETE FROM high_jump_attempts
        WHERE event_id = ?
        """, (event_id,))

        # Remove High Jump heights
        cur.execute("""
        DELETE FROM high_jump_heights
        WHERE event_id = ?
        """, (event_id,))

        # Remove finalists
        cur.execute("""
        DELETE FROM finals
        WHERE event_id = ?
        """, (event_id,))

        # Results depend on heat IDs
        cur.execute("""
        DELETE FROM results
        WHERE heat_id IN (
            SELECT id
            FROM heats
            WHERE event_id = ?
        )
        """, (event_id,))

        # Heat entries depend on heat IDs
        cur.execute("""
        DELETE FROM heat_entries
        WHERE heat_id IN (
            SELECT id
            FROM heats
            WHERE event_id = ?
        )
        """, (event_id,))

        # Remove heats
        cur.execute("""
        DELETE FROM heats
        WHERE event_id = ?
        """, (event_id,))

        # Remove event entries
        cur.execute("""
        DELETE FROM event_entries
        WHERE event_id = ?
        """, (event_id,))

        # Finally remove event itself
        cur.execute("""
        DELETE FROM events
        WHERE id = ?
        """, (event_id,))

        conn.commit()
        conn.close()

        QMessageBox.information(
            self,
            "Event Deleted",
            "Event deleted successfully."
        )

        self.clear_selection()
        self.load_events()


    # =========================
    # CLEAR SELECTION
    # =========================
    def clear_selection(self):

        self.selected_event_id = None

        self.event_list.clearSelection()

        self.event_name.clear()

        if self.gender_combo.count() > 0:
            self.gender_combo.setCurrentIndex(0)

        if self.age_combo.count() > 0:
            self.age_combo.setCurrentIndex(0)

        if self.event_type.count() > 0:
            self.event_type.setCurrentIndex(0)

        if self.format_combo.count() > 0:
            self.format_combo.setCurrentIndex(0)

        self.start_time.clear()
        self.heat_interval.setText("3")
        self.final_time.clear()

        self.update_format_availability()

