    def load_events(self):

        self.event_combo.clear()

        meeting_id = get_active_meeting()

        if not meeting_id:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        cur.execute("""
        SELECT
            id,
            event_name,
            gender,
            age_group
        FROM events
        WHERE meeting_id = ?
        AND event_type = 'Track'
        AND COALESCE(
            competition_format,
            'Timed Finals'
        ) = 'Normal Heats + Final'
        ORDER BY
            event_name,
            gender,
            age_group
        """, (meeting_id,))

        rows = cur.fetchall()

        conn.close()

        for (
            event_id,
            name,
            gender,
            age_group
        ) in rows:

            self.event_combo.addItem(
                (
                    f"{name} "
                    f"({gender} {age_group})"
                ),
                event_id
            )


    def load_finals(self):

        self.table.setRowCount(0)

        event_id = (
            self.event_combo.currentData()
        )

        if not event_id:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # =========================
        # LOAD FINALISTS
        # =========================
        cur.execute("""
        SELECT
            f.athlete_id,
            a.full_name,
            f.seed_position
        FROM finals f

        JOIN athletes a
            ON f.athlete_id = a.id

        WHERE f.event_id = ?

        ORDER BY f.seed_position
        """, (event_id,))

        finalists = cur.fetchall()

        if not finalists:

            conn.close()

            return

        # =========================
        # LOAD EXISTING RESULTS
        # =========================
        cur.execute("""
        SELECT
            athlete_id,
            lane_number,
            performance,
            position
        FROM final_results
        WHERE event_id = ?
        """, (event_id,))

        saved_results = {
            row[0]: (
                row[1],
                row[2],
                row[3]
            )
            for row in cur.fetchall()
        }

        conn.close()

        # Preferred championship lanes
        lane_order = [
            4, 5, 3, 6,
            2, 7, 1, 8
        ]

        self.table.setRowCount(
            len(finalists)
        )

        for row, finalist in enumerate(
            finalists
        ):

            athlete_id = finalist[0]
            athlete_name = finalist[1]
            seed = finalist[2]

            # Default lane from seed
            if 1 <= seed <= len(
                lane_order
            ):

                default_lane = (
                    lane_order[
                        seed - 1
                    ]
                )

            else:

                default_lane = ""

            saved_lane, performance, position = (
                saved_results.get(
                    athlete_id,
                    (
                        None,
                        "",
                        ""
                    )
                )
            )

            # Preserve saved lane if one exists
            if (
                saved_lane is not None
                and saved_lane != 0
            ):

                lane = saved_lane

            else:

                lane = default_lane

            if performance is None:
                performance = ""

            if position is None:
                position = ""

            # =========================
            # LANE - READ ONLY
            # =========================
            lane_item = QTableWidgetItem(
                str(lane)
            )

            lane_item.setFlags(
                lane_item.flags()
                & ~Qt.ItemIsEditable
            )

            self.table.setItem(
                row,
                0,
                lane_item
            )

            # =========================
            # ATHLETE - READ ONLY
            # =========================
            athlete_item = QTableWidgetItem(
                athlete_name
            )

            athlete_item.setData(
                Qt.UserRole,
                athlete_id
            )

            athlete_item.setFlags(
                athlete_item.flags()
                & ~Qt.ItemIsEditable
            )

            self.table.setItem(
                row,
                1,
                athlete_item
            )

            # =========================
            # PERFORMANCE - EDITABLE
            # =========================
            performance_item = (
                QTableWidgetItem(
                    str(performance)
                )
            )

            self.table.setItem(
                row,
                2,
                performance_item
            )

            # =========================
            # POSITION - READ ONLY
            # =========================
            position_item = (
                QTableWidgetItem(
                    str(position)
                )
            )

            position_item.setFlags(
                position_item.flags()
                & ~Qt.ItemIsEditable
            )

            self.table.setItem(
                row,
                3,
                position_item
            )

    def save_final_results(self):

        event_id = (
            self.event_combo.currentData()
        )

        if not event_id:

            QMessageBox.warning(
                self,
                "No Event Selected",
                "Please select a final event first."
            )

            return

        valid_codes = {
            "DNS",
            "DNF",
            "DQ"
        }

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        for row in range(
            self.table.rowCount()
        ):

            athlete_item = (
                self.table.item(
                    row,
                    1
                )
            )

            if not athlete_item:
                continue

            athlete_id = (
                athlete_item.data(
                    Qt.UserRole
                )
            )

            lane_item = (
                self.table.item(
                    row,
                    0
                )
            )

            performance_item = (
                self.table.item(
                    row,
                    2
                )
            )

            # =========================
            # LANE
            # =========================
            lane = 0

            if lane_item:

                try:

                    lane = int(
                        lane_item.text()
                    )

                except ValueError:

                    lane = 0

            # =========================
            # PERFORMANCE
            # =========================
            performance = ""

            if performance_item:

                performance = (
                    performance_item
                    .text()
                    .strip()
                )

            # =========================
            # VALIDATE
            # =========================
            if performance:

                upper_value = (
                    performance.upper()
                )

                if upper_value in valid_codes:

                    performance = (
                        upper_value
                    )

                else:

                    try:

                        value = float(
                            performance
                        )

                        if value < 0:

                            raise ValueError

                    except ValueError:

                        athlete_name = (
                            athlete_item.text()
                        )

                        conn.close()

                        QMessageBox.warning(
                            self,
                            "Invalid Performance",
                            (
                                f"Invalid result for:\n\n"
                                f"{athlete_name}\n\n"
                                "Enter a positive number "
                                "or one of these codes:\n\n"
                                "DNS = Did Not Start\n"
                                "DNF = Did Not Finish\n"
                                "DQ = Disqualified"
                            )
                        )

                        return

            # =========================
            # SAVE / UPDATE
            # =========================
            cur.execute("""
            INSERT INTO final_results
            (
                event_id,
                athlete_id,
                lane_number,
                performance
            )
            VALUES (?, ?, ?, ?)

            ON CONFLICT(
                event_id,
                athlete_id
            )

            DO UPDATE SET
                lane_number =
                    excluded.lane_number,
                performance =
                    excluded.performance
            """, (
                event_id,
                athlete_id,
                lane,
                performance
            ))

        conn.commit()
        conn.close()

        # Recalculate positions
        self.calculate_final_positions(
            event_id
        )

        # Rebuild team points
        self.award_final_points(
            event_id
        )

        # Refresh table
        self.load_finals()

        QMessageBox.information(
            self,
            "Final Results Saved",
            "Final results saved successfully."
        )

    def calculate_final_positions(
        self,
        event_id
    ):

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # =========================
        # CLEAR OLD POSITIONS
        # =========================
        cur.execute("""
        UPDATE final_results
        SET position = NULL
        WHERE event_id = ?
        """, (
            event_id,
        ))

        # =========================
        # EVENT TYPE
        # =========================
        cur.execute("""
        SELECT event_type
        FROM events
        WHERE id = ?
        """, (
            event_id,
        ))

        row = cur.fetchone()

        if not row:

            conn.commit()
            conn.close()

            return

        event_type = row[0]

        # =========================
        # LOAD VALID RESULTS
        # =========================
        cur.execute("""
        SELECT
            athlete_id,
            performance
        FROM final_results
        WHERE event_id = ?
        """, (
            event_id,
        ))

        rows = cur.fetchall()

        athletes = []

        for (
            athlete_id,
            performance
        ) in rows:

            try:

                value = float(
                    performance
                )

                athletes.append(
                    (
                        athlete_id,
                        value
                    )
                )

            except (
                ValueError,
                TypeError
            ):

                # Blank / DNS / DNF / DQ
                continue

        # =========================
        # SORT RESULTS
        # =========================
        if event_type == "Track":

            athletes.sort(
                key=lambda x: x[1]
            )

        else:

            athletes.sort(
                key=lambda x: x[1],
                reverse=True
            )

        # =========================
        # ASSIGN POSITIONS
        # WITH TIES
        # =========================

        previous_value = None
        previous_position = None

        for index, (
            athlete_id,
            value
        ) in enumerate(
            athletes,
            start=1
        ):

            if (
                previous_value is not None
                and value == previous_value
            ):

                position = (
                    previous_position
                )

            else:

                position = index

            cur.execute("""
            UPDATE final_results
            SET position = ?
            WHERE event_id = ?
            AND athlete_id = ?
            """, (
                position,
                event_id,
                athlete_id
            ))

            previous_value = value
            previous_position = position

        conn.commit()
        conn.close()

    def award_final_points(
        self,
        event_id
    ):

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # Find the meeting this event belongs to
        cur.execute("""
        SELECT meeting_id
        FROM events
        WHERE id = ?
        """, (event_id,))

        row = cur.fetchone()

        if not row:
            conn.close()
            return

        meeting_id = row[0]

        # Remove old points for this event.
        # This prevents duplicate or outdated points
        # if final results are edited later.
        cur.execute("""
        DELETE FROM awarded_points
        WHERE event_id = ?
        """, (event_id,))

        # Load final results together with
        # the athlete's team
        cur.execute("""
        SELECT
            fr.athlete_id,
            fr.position,
            a.team_id
        FROM final_results fr
        JOIN athletes a
            ON fr.athlete_id = a.id
        WHERE fr.event_id = ?
        AND fr.position IS NOT NULL
        """, (event_id,))

        results = cur.fetchall()

        for athlete_id, position, team_id in results:

            # Find how many points this position earns
            cur.execute("""
            SELECT points
            FROM points_config
            WHERE meeting_id = ?
            AND position = ?
            """, (
                meeting_id,
                position
            ))

            points_row = cur.fetchone()

            # No points configured for this position
            if not points_row:
                continue

            points = points_row[0]

            cur.execute("""
            INSERT INTO awarded_points
            (
                meeting_id,
                event_id,
                athlete_id,
                team_id,
                position,
                points
            )
            VALUES (?, ?, ?, ?, ?, ?)
            """, (
                meeting_id,
                event_id,
                athlete_id,
                team_id,
                position,
                points
            ))

        conn.commit()
        conn.close()

