    def load_events(self):

        current_event_id = (
            self.event_combo.currentData()
        )

        self.event_combo.blockSignals(True)
        self.event_combo.clear()

        meeting_id = get_active_meeting()

        if not meeting_id:

            self.event_combo.blockSignals(False)
            self.status_label.setText(
                "No active meeting selected."
            )
            self.table.setRowCount(0)
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        cur.execute("""
        SELECT
            id,
            event_name,
            gender,
            age_group,
            event_type
        FROM events
        WHERE meeting_id = ?
        AND COALESCE(
            competition_format,
            'Timed Finals'
        ) = 'Timed Finals'
        ORDER BY
            event_name,
            gender,
            age_group
        """, (
            meeting_id,
        ))

        events = cur.fetchall()
        conn.close()

        restore_index = -1

        for index, (
            event_id,
            event_name,
            gender,
            age_group,
            event_type
        ) in enumerate(events):

            self.event_combo.addItem(
                (
                    f"{event_name} "
                    f"({gender} {age_group}) "
                    f"- {event_type}"
                ),
                event_id
            )

            if event_id == current_event_id:
                restore_index = index

        if restore_index >= 0:
            self.event_combo.setCurrentIndex(
                restore_index
            )

        self.event_combo.blockSignals(False)

        if not events:
            self.status_label.setText(
                "No Timed Final events exist in the active meeting."
            )
            self.table.setRowCount(0)

    # =========================
    # LOAD OVERALL RESULTS
    # =========================
    def load_results(self):

        self.table.setRowCount(0)

        meeting_id = get_active_meeting()
        event_id = (
            self.event_combo.currentData()
        )

        if not meeting_id or not event_id:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        cur.execute("""
        SELECT
            event_name,
            gender,
            age_group,
            event_type,
            COALESCE(
                competition_format,
                'Timed Finals'
            )
        FROM events
        WHERE id = ?
        AND meeting_id = ?
        """, (
            event_id,
            meeting_id
        ))

        event = cur.fetchone()

        if not event:
            conn.close()
            return

        (
            event_name,
            gender,
            age_group,
            event_type,
            competition_format
        ) = event

        if competition_format != "Timed Finals":

            conn.close()
            self.status_label.setText(
                "This event is not using Timed Finals."
            )
            return

        # Count all active athletes who are expected
        # to have an official result for the event.
        cur.execute("""
        SELECT COUNT(DISTINCT ee.athlete_id)
        FROM event_entries ee

        JOIN athletes a
            ON ee.athlete_id = a.id

        WHERE ee.meeting_id = ?
        AND ee.event_id = ?
        AND ee.status = 'Active'
        AND a.status = 'Active'
        """, (
            meeting_id,
            event_id
        ))

        expected_count = (
            cur.fetchone()[0]
        )

        cur.execute("""
        SELECT COUNT(DISTINCT fr.athlete_id)
        FROM final_results fr

        JOIN athletes a
            ON fr.athlete_id = a.id

        JOIN event_entries ee
            ON ee.event_id = fr.event_id
            AND ee.athlete_id = fr.athlete_id

        WHERE fr.event_id = ?
        AND ee.meeting_id = ?
        AND ee.status = 'Active'
        AND a.status = 'Active'
        """, (
            event_id,
            meeting_id
        ))

        recorded_count = (
            cur.fetchone()[0]
        )

        # One row per active event entry. final_results
        # supplies the overall official performance and
        # position. Track heat/lane information is looked
        # up from the athlete's generated running group.
        cur.execute("""
        SELECT
            ee.athlete_id,
            a.full_name,
            COALESCE(t.name, 'No Team'),
            fr.performance,
            fr.position,
            (
                SELECT h.heat_number
                FROM heat_entries he

                JOIN heats h
                    ON he.heat_id = h.id

                WHERE h.event_id = ee.event_id
                AND he.athlete_id = ee.athlete_id

                ORDER BY h.heat_number
                LIMIT 1
            ) AS heat_number,
            (
                SELECT he.lane_number
                FROM heat_entries he

                JOIN heats h
                    ON he.heat_id = h.id

                WHERE h.event_id = ee.event_id
                AND he.athlete_id = ee.athlete_id

                ORDER BY h.heat_number
                LIMIT 1
            ) AS lane_number,
            ap.points
        FROM event_entries ee

        JOIN athletes a
            ON ee.athlete_id = a.id

        LEFT JOIN teams t
            ON a.team_id = t.id

        LEFT JOIN final_results fr
            ON fr.event_id = ee.event_id
            AND fr.athlete_id = ee.athlete_id

        LEFT JOIN awarded_points ap
            ON ap.event_id = ee.event_id
            AND ap.athlete_id = ee.athlete_id

        WHERE ee.meeting_id = ?
        AND ee.event_id = ?
        AND ee.status = 'Active'
        AND a.status = 'Active'

        ORDER BY
            CASE
                WHEN fr.position IS NULL
                THEN 1
                ELSE 0
            END,
            fr.position,
            a.full_name
        """, (
            meeting_id,
            event_id
        ))

        rows = cur.fetchall()
        conn.close()

        self.table.setRowCount(
            len(rows)
        )

        for row_number, (
            athlete_id,
            athlete_name,
            team_name,
            performance,
            position,
            heat_number,
            lane_number,
            points
        ) in enumerate(rows):

            if performance is None:
                performance = ""

            if position is None:
                position = ""

            if heat_number is None:
                heat_number = ""

            if lane_number is None:
                lane_number = ""

            if points is None:
                points = ""
            elif float(points).is_integer():
                points = int(points)

            values = [
                position,
                athlete_name,
                team_name,
                performance,
                heat_number,
                lane_number,
                points
            ]

            for column, value in enumerate(
                values
            ):

                item = QTableWidgetItem(
                    str(value)
                )

                item.setFlags(
                    item.flags()
                    & ~Qt.ItemIsEditable
                )

                if column == 1:
                    item.setData(
                        Qt.UserRole,
                        athlete_id
                    )

                self.table.setItem(
                    row_number,
                    column,
                    item
                )

        complete = (
            expected_count > 0
            and recorded_count == expected_count
        )

        if complete:
            status_text = (
                "COMPLETE - official Timed Final "
                "results are available."
            )
        else:
            status_text = (
                "IN PROGRESS - results are still "
                "missing for one or more athletes."
            )

        self.status_label.setText(
            (
                f"{event_name} "
                f"({gender} {age_group}) | "
                f"{event_type} | "
                f"Official results: "
                f"{recorded_count} / "
                f"{expected_count} | "
                f"{status_text}"
            )
        )

    def refresh_screen(self):

        self.load_events()
        self.load_results()


