    def load_points(self):

        meeting_id = get_active_meeting()

        if not meeting_id:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        cur.execute("""
        SELECT
            position,
            points
        FROM points_config
        WHERE meeting_id = ?
        """, (meeting_id,))

        saved_points = {
            position: points
            for position, points
            in cur.fetchall()
        }

        conn.close()

        for row in range(8):

            position = row + 1

            if position in saved_points:

                points = saved_points[position]

                # Show whole numbers nicely
                if float(points).is_integer():
                    points = int(points)

                self.table.setItem(
                    row,
                    1,
                    QTableWidgetItem(
                        str(points)
                    )
                )


    def save_points(self):

        meeting_id = get_active_meeting()

        if not meeting_id:

            QMessageBox.warning(
                self,
                "No Active Meeting",
                "Select an active meeting first."
            )

            return

        points_to_save = []

        for row in range(
            self.table.rowCount()
        ):

            position = row + 1

            points_item = self.table.item(
                row,
                1
            )

            if not points_item:

                QMessageBox.warning(
                    self,
                    "Missing Points",
                    f"Enter points for position {position}."
                )

                return

            text = points_item.text().strip()

            try:

                points = float(text)

            except ValueError:

                QMessageBox.warning(
                    self,
                    "Invalid Points",
                    f"Position {position} does not contain a valid number."
                )

                return

            if points < 0:

                QMessageBox.warning(
                    self,
                    "Invalid Points",
                    "Points cannot be negative."
                )

                return

            points_to_save.append(
                (position, points)
            )

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        for position, points in points_to_save:

            cur.execute("""
            INSERT INTO points_config
            (
                meeting_id,
                position,
                points
            )
            VALUES (?, ?, ?)

            ON CONFLICT(meeting_id, position)
            DO UPDATE SET
                points = excluded.points
            """, (
                meeting_id,
                position,
                points
            ))

        conn.commit()
        conn.close()

        QMessageBox.information(
            self,
            "Points Saved",
            "Points system saved successfully."
        )

