class FieldResultsScreen(QWidget):

    def __init__(self):
        super().__init__()
        _apply_modern_screen_theme(self, "#F0B400")
        root=QVBoxLayout(self); root.setContentsMargins(18,10,18,18); root.setSpacing(12)
        select_card,select=_modern_card("Measured Field Event","Enter attempts and calculate final ranking","#D99B00","trophy")
        row=QHBoxLayout(); self.event_combo=QComboBox(); load_button=QPushButton("Load Field Event"); load_button.clicked.connect(self.load_event); _style_primary_button(load_button,"#D99B00"); row.addWidget(self.event_combo,1); row.addWidget(load_button); select.addLayout(row)
        note=QLabel("Enter a distance for each attempt. Use X for a foul and - for a pass. Attempts 4-6 are the final three attempts where applicable."); note.setWordWrap(True); note.setStyleSheet("color:#687A92;font-size:11px;"); select.addWidget(note); root.addWidget(select_card)
        table_card,tb=_modern_card("Attempts & Ranking","Best performances and positions are calculated automatically","#D99B00","document")
        self.table=QTableWidget(); self.table.setColumnCount(9); self.table.setHorizontalHeaderLabels(["Athlete","Attempt 1","Attempt 2","Attempt 3","Attempt 4","Attempt 5","Attempt 6","Best","Position"]); self.table.setMinimumHeight(430); tb.addWidget(self.table,1)
        save_button=QPushButton("Save Field Results"); save_button.clicked.connect(self.save_results); _style_primary_button(save_button,"#D99B00"); tb.addWidget(save_button); root.addWidget(table_card,1)
        self.load_events(); self.event_combo.currentIndexChanged.connect(self.load_event); self.load_event()

    def load_events(self):

        self.event_combo.clear()

        meeting_id = get_active_meeting()

        if not meeting_id:
            return

        conn = sqlite3.connect(
            DB_NAME
        )

        cur = conn.cursor()

        cur.execute("""
        SELECT
            id,
            event_name,
            gender,
            age_group
        FROM events
        WHERE meeting_id = ?
        AND event_type = 'Field'
        ORDER BY
            event_name,
            gender,
            age_group
        """, (
            meeting_id,
        ))

        rows = cur.fetchall()

        conn.close()

        for (
            event_id,
            event_name,
            gender,
            age_group
        ) in rows:

            self.event_combo.addItem(
                (
                    f"{event_name} "
                    f"({gender} {age_group})"
                ),
                event_id
            )

    # =========================
    # DETERMINE FINAL-ROUND
    # QUALIFIERS
    # =========================
    def determine_final_round_qualifiers(
        self,
        athlete_ids,
        attempts
    ):

        # =========================
        # 8 OR FEWER ATHLETES
        # =========================
        if len(athlete_ids) <= 8:

            return set(
                athlete_ids
            ), True

        # =========================
        # FIRST 3 MUST BE COMPLETE
        # =========================
        for athlete_id in athlete_ids:

            for attempt_number in range(
                1,
                4
            ):

                value = attempts.get(
                    (
                        athlete_id,
                        attempt_number
                    ),
                    ""
                )

                if (
                    value is None
                    or not str(value).strip()
                ):

                    return set(), False

        rankings = []

        # =========================
        # RANK FIRST 3 ATTEMPTS
        # =========================
        for athlete_id in athlete_ids:

            numeric_attempts = []

            for attempt_number in range(
                1,
                4
            ):

                value = attempts.get(
                    (
                        athlete_id,
                        attempt_number
                    ),
                    ""
                )

                try:

                    numeric_value = float(
                        value
                    )

                except (
                    ValueError,
                    TypeError
                ):

                    continue

                numeric_attempts.append(
                    numeric_value
                )

            # No valid mark means the
            # athlete cannot advance.
            if not numeric_attempts:
                continue

            ordered = sorted(
                numeric_attempts,
                reverse=True
            )

            # Best mark wins.
            # Second-best and third-best
            # are used as tie-breakers.
            tie_key = tuple(
                ordered
                + [-1.0] * (
                    3 - len(ordered)
                )
            )

            rankings.append(
                (
                    athlete_id,
                    tie_key
                )
            )

        rankings.sort(
            key=lambda item: item[1],
            reverse=True
        )

        # Fewer than 8 athletes with
        # valid marks: all advance.
        if len(rankings) <= 8:

            return {
                athlete_id
                for athlete_id, tie_key
                in rankings
            }, True

        # =========================
        # TOP 8 CUTOFF
        # =========================
        cutoff_key = rankings[7][1]

        qualifiers = {
            athlete_id
            for athlete_id, tie_key
            in rankings
            if tie_key >= cutoff_key
        }

        return qualifiers, True

    # =========================
    # LOAD EVENT
    # =========================

    def load_event(self):

        self.table.setRowCount(0)

        event_id = (
            self.event_combo.currentData()
        )

        meeting_id = get_active_meeting()

        if (
            not meeting_id
            or not event_id
        ):
            return

        conn = sqlite3.connect(
            DB_NAME
        )

        cur = conn.cursor()

        cur.execute("""
        SELECT
            a.id,
            a.full_name
        FROM event_entries ee

        JOIN athletes a
            ON ee.athlete_id = a.id

        WHERE ee.meeting_id = ?
        AND ee.event_id = ?
        AND ee.status = 'Active'
        AND a.status = 'Active'

        ORDER BY a.full_name
        """, (
            meeting_id,
            event_id
        ))

        athletes = cur.fetchall()

        cur.execute("""
        SELECT
            athlete_id,
            attempt_number,
            performance
        FROM field_attempts
        WHERE event_id = ?
        """, (
            event_id,
        ))

        saved_attempts = {}

        for (
            athlete_id,
            attempt_number,
            performance
        ) in cur.fetchall():

            saved_attempts[
                (
                    athlete_id,
                    attempt_number
                )
            ] = performance

        cur.execute("""
        SELECT
            athlete_id,
            performance,
            position
        FROM final_results
        WHERE event_id = ?
        """, (
            event_id,
        ))

        saved_results = {
            row[0]: (
                row[1],
                row[2]
            )
            for row in cur.fetchall()
        }

        conn.close()

        athlete_ids = [
            athlete_id
            for athlete_id, athlete_name
            in athletes
        ]

        qualifiers, preliminary_complete = (
            self.determine_final_round_qualifiers(
                athlete_ids,
                saved_attempts
            )
        )

        self.table.setRowCount(
            len(athletes)
        )

        for row, (
            athlete_id,
            athlete_name
        ) in enumerate(
            athletes
        ):

            athlete_item = (
                QTableWidgetItem(
                    athlete_name
                )
            )

            athlete_item.setData(
                Qt.UserRole,
                athlete_id
            )

            athlete_item.setFlags(
                athlete_item.flags()
                & ~Qt.ItemIsEditable
            )

            self.table.setItem(
                row,
                0,
                athlete_item
            )

            for attempt_number in range(
                1,
                7
            ):

                value = saved_attempts.get(
                    (
                        athlete_id,
                        attempt_number
                    ),
                    ""
                )

                # =========================
                # LOCK ATTEMPTS 4-6
                # =========================
                final_round_locked = (
                    attempt_number >= 4
                    and len(athletes) > 8
                    and (
                        not preliminary_complete
                        or athlete_id
                        not in qualifiers
                    )
                )

                if final_round_locked:

                    value = ""

                item = QTableWidgetItem(
                    str(
                        value
                        if value is not None
                        else ""
                    )
                )

                if final_round_locked:

                    item.setFlags(
                        item.flags()
                        & ~Qt.ItemIsEditable
                    )

                self.table.setItem(
                    row,
                    attempt_number,
                    item
                )

            best, position = (
                saved_results.get(
                    athlete_id,
                    (
                        "",
                        ""
                    )
                )
            )

            if best is None:
                best = ""

            if position is None:
                position = ""

            best_item = QTableWidgetItem(
                str(best)
            )

            best_item.setFlags(
                best_item.flags()
                & ~Qt.ItemIsEditable
            )

            self.table.setItem(
                row,
                7,
                best_item
            )

            position_item = (
                QTableWidgetItem(
                    str(position)
                )
            )

            position_item.setFlags(
                position_item.flags()
                & ~Qt.ItemIsEditable
            )

            self.table.setItem(
                row,
                8,
                position_item
            )

    # =========================
    # SAVE FIELD RESULTS
    # =========================

    def save_results(self):

        event_id = (
            self.event_combo.currentData()
        )

        meeting_id = get_active_meeting()

        if (
            not meeting_id
            or not event_id
        ):

            QMessageBox.warning(
                self,
                "No Event Selected",
                "Select a field event first."
            )

            return

        valid_codes = {
            "X",
            "-"
        }

        # =========================
        # READ + VALIDATE TABLE
        # =========================
        athlete_ids = []
        table_attempts = {}

        for row in range(
            self.table.rowCount()
        ):

            athlete_item = (
                self.table.item(
                    row,
                    0
                )
            )

            if not athlete_item:
                continue

            athlete_id = (
                athlete_item.data(
                    Qt.UserRole
                )
            )

            athlete_name = (
                athlete_item.text()
            )

            athlete_ids.append(
                athlete_id
            )

            for attempt_number in range(
                1,
                7
            ):

                item = self.table.item(
                    row,
                    attempt_number
                )

                performance = ""

                if item:

                    performance = (
                        item.text()
                        .strip()
                    )

                if not performance:

                    table_attempts[
                        (
                            athlete_id,
                            attempt_number
                        )
                    ] = ""

                    continue

                upper_value = (
                    performance.upper()
                )

                if upper_value in valid_codes:

                    table_attempts[
                        (
                            athlete_id,
                            attempt_number
                        )
                    ] = upper_value

                    continue

                try:

                    numeric_value = float(
                        performance
                    )

                    if numeric_value < 0:
                        raise ValueError

                except ValueError:

                    QMessageBox.warning(
                        self,
                        "Invalid Attempt",
                        (
                            f"Invalid attempt for:\n\n"
                            f"{athlete_name}\n\n"
                            "Enter a positive number, "
                            "X for a foul, or - for a pass."
                        )
                    )

                    return

                table_attempts[
                    (
                        athlete_id,
                        attempt_number
                    )
                ] = performance

        # =========================
        # DETERMINE FINAL-ROUND
        # QUALIFIERS
        # =========================
        qualifiers, preliminary_complete = (
            self.determine_final_round_qualifiers(
                athlete_ids,
                table_attempts
            )
        )

        if len(athlete_ids) <= 8:

            final_round_allowed = set(
                athlete_ids
            )

        elif preliminary_complete:

            final_round_allowed = set(
                qualifiers
            )

        else:

            final_round_allowed = set()

        # =========================
        # CHECK IF EVENT COMPLETE
        # =========================
        if len(athlete_ids) <= 8:

            event_complete = (
                bool(athlete_ids)
                and all(
                    str(
                        table_attempts.get(
                            (
                                athlete_id,
                                attempt_number
                            ),
                            ""
                        )
                    ).strip()
                    for athlete_id
                    in athlete_ids
                    for attempt_number
                    in range(1, 7)
                )
            )

        else:

            event_complete = (
                preliminary_complete
                and all(
                    str(
                        table_attempts.get(
                            (
                                athlete_id,
                                attempt_number
                            ),
                            ""
                        )
                    ).strip()
                    for athlete_id
                    in final_round_allowed
                    for attempt_number
                    in range(4, 7)
                )
            )

        conn = sqlite3.connect(
            DB_NAME
        )

        cur = conn.cursor()

        try:

            for athlete_id in athlete_ids:

                numeric_attempts = []

                for attempt_number in range(
                    1,
                    7
                ):

                    # =========================
                    # BLOCK NON-QUALIFIERS
                    # FROM ATTEMPTS 4-6
                    # =========================
                    if (
                        attempt_number >= 4
                        and athlete_id
                        not in final_round_allowed
                    ):

                        cur.execute("""
                        DELETE FROM field_attempts
                        WHERE event_id = ?
                        AND athlete_id = ?
                        AND attempt_number = ?
                        """, (
                            event_id,
                            athlete_id,
                            attempt_number
                        ))

                        continue

                    performance = (
                        table_attempts.get(
                            (
                                athlete_id,
                                attempt_number
                            ),
                            ""
                        )
                    )

                    if not performance:

                        cur.execute("""
                        DELETE FROM field_attempts
                        WHERE event_id = ?
                        AND athlete_id = ?
                        AND attempt_number = ?
                        """, (
                            event_id,
                            athlete_id,
                            attempt_number
                        ))

                        continue

                    try:

                        numeric_value = float(
                            performance
                        )

                        numeric_attempts.append(
                            numeric_value
                        )

                    except (
                        ValueError,
                        TypeError
                    ):

                        pass

                    cur.execute("""
                    INSERT INTO field_attempts
                    (
                        meeting_id,
                        event_id,
                        athlete_id,
                        attempt_number,
                        performance
                    )
                    VALUES (?, ?, ?, ?, ?)

                    ON CONFLICT(
                        event_id,
                        athlete_id,
                        attempt_number
                    )

                    DO UPDATE SET
                        performance =
                            excluded.performance
                    """, (
                        meeting_id,
                        event_id,
                        athlete_id,
                        attempt_number,
                        performance
                    ))

                # =========================
                # BEST PERFORMANCE
                # =========================
                if numeric_attempts:

                    best = max(
                        numeric_attempts
                    )

                    best_text = (
                        f"{best:g}"
                    )

                else:

                    best_text = ""

                cur.execute("""
                INSERT INTO final_results
                (
                    event_id,
                    athlete_id,
                    lane_number,
                    performance
                )
                VALUES (?, ?, 0, ?)

                ON CONFLICT(
                    event_id,
                    athlete_id
                )

                DO UPDATE SET
                    lane_number = 0,
                    performance =
                        excluded.performance
                """, (
                    event_id,
                    athlete_id,
                    best_text
                ))

            conn.commit()

        except sqlite3.Error as error:

            conn.rollback()
            conn.close()

            QMessageBox.critical(
                self,
                "Save Failed",
                (
                    "Field results could not "
                    "be saved.\n\n"
                    f"Database error:\n{error}"
                )
            )

            return

        conn.close()

        self.calculate_positions(
            event_id
        )

        # =========================
        # POINTS ONLY AFTER EVENT
        # IS COMPLETE
        # =========================
        if event_complete:

            self.award_points(
                event_id
            )

        else:

            points_conn = sqlite3.connect(
                DB_NAME
            )

            points_cur = (
                points_conn.cursor()
            )

            points_cur.execute("""
            DELETE FROM awarded_points
            WHERE event_id = ?
            """, (
                event_id,
            ))

            points_conn.commit()
            points_conn.close()

        self.load_event()

        # =========================
        # STATUS MESSAGE
        # =========================
        if event_complete:

            message = (
                "Field event completed.\n\n"
                "Final positions and points "
                "have been updated."
            )

        elif (
            len(athlete_ids) > 8
            and preliminary_complete
        ):

            message = (
                "The first three rounds "
                "have been saved.\n\n"
                f"{len(final_round_allowed)} "
                "athlete(s) may now complete "
                "Attempts 4-6."
            )

        elif len(athlete_ids) > 8:

            message = (
                "Results saved.\n\n"
                "Complete Attempts 1-3 for "
                "every athlete. Attempts 4-6 "
                "will then unlock for the "
                "qualifying athletes."
            )

        else:

            message = (
                "Results saved.\n\n"
                "There are 8 or fewer athletes, "
                "so every athlete may complete "
                "Attempts 1-6."
            )

        QMessageBox.information(
            self,
            "Field Results Saved",
            message
        )

    # =========================
    # CALCULATE FIELD POSITIONS
    # =========================
    def calculate_positions(
        self,
        event_id
    ):

        conn = sqlite3.connect(
            DB_NAME
        )

        cur = conn.cursor()

        cur.execute("""
        UPDATE final_results
        SET position = NULL
        WHERE event_id = ?
        """, (
            event_id,
        ))

        cur.execute("""
        SELECT
            athlete_id,
            performance
        FROM field_attempts
        WHERE event_id = ?
        ORDER BY
            athlete_id,
            attempt_number
        """, (
            event_id,
        ))

        athlete_attempts = {}

        for (
            athlete_id,
            performance
        ) in cur.fetchall():

            try:

                value = float(
                    performance
                )

            except (
                ValueError,
                TypeError
            ):

                continue

            if athlete_id not in (
                athlete_attempts
            ):

                athlete_attempts[
                    athlete_id
                ] = []

            athlete_attempts[
                athlete_id
            ].append(
                value
            )

        rankings = []

        for (
            athlete_id,
            attempts
        ) in athlete_attempts.items():

            ordered = sorted(
                attempts,
                reverse=True
            )

            tie_key = tuple(
                ordered
                + [-1.0] * (
                    6 - len(ordered)
                )
            )

            rankings.append(
                (
                    athlete_id,
                    tie_key
                )
            )

        rankings.sort(
            key=lambda x: x[1],
            reverse=True
        )

        previous_key = None
        previous_position = None

        for index, (
            athlete_id,
            tie_key
        ) in enumerate(
            rankings,
            start=1
        ):

            if (
                previous_key is not None
                and tie_key == previous_key
            ):

                position = (
                    previous_position
                )

            else:

                position = index

            cur.execute("""
            UPDATE final_results
            SET position = ?
            WHERE event_id = ?
            AND athlete_id = ?
            """, (
                position,
                event_id,
                athlete_id
            ))

            previous_key = tie_key
            previous_position = position

        conn.commit()
        conn.close()


    # =========================
    # AWARD FIELD POINTS
    # =========================
    def award_points(
        self,
        event_id
    ):

        conn = sqlite3.connect(
            DB_NAME
        )

        cur = conn.cursor()

        cur.execute("""
        SELECT meeting_id
        FROM events
        WHERE id = ?
        """, (
            event_id,
        ))

        row = cur.fetchone()

        if not row:

            conn.close()
            return

        meeting_id = row[0]

        cur.execute("""
        DELETE FROM awarded_points
        WHERE event_id = ?
        """, (
            event_id,
        ))

        cur.execute("""
        SELECT
            fr.athlete_id,
            fr.position,
            a.team_id
        FROM final_results fr

        JOIN athletes a
            ON fr.athlete_id = a.id

        WHERE fr.event_id = ?
        AND fr.position IS NOT NULL
        """, (
            event_id,
        ))

        results = cur.fetchall()

        for (
            athlete_id,
            position,
            team_id
        ) in results:

            cur.execute("""
            SELECT points
            FROM points_config
            WHERE meeting_id = ?
            AND position = ?
            """, (
                meeting_id,
                position
            ))

            points_row = (
                cur.fetchone()
            )

            if not points_row:
                continue

            points = points_row[0]

            cur.execute("""
            INSERT INTO awarded_points
            (
                meeting_id,
                event_id,
                athlete_id,
                team_id,
                position,
                points
            )
            VALUES (?, ?, ?, ?, ?, ?)

            ON CONFLICT(
                event_id,
                athlete_id
            )

            DO UPDATE SET
                team_id =
                    excluded.team_id,
                position =
                    excluded.position,
                points =
                    excluded.points
            """, (
                meeting_id,
                event_id,
                athlete_id,
                team_id,
                position,
                points
            ))

        conn.commit()
        conn.close()

