    def event_type_for_name(
        self,
        event_name
    ):

        if event_name == "High Jump":
            return "High Jump"

        if event_name in self.FIELD_EVENTS:
            return "Field"

        return "Track"

    # =========================
    # STANDARD EVENTS FOR AGE
    # =========================
    def standard_events_for_age(
        self,
        age_group
    ):

        entries = []

        if age_group in self.MALE_EVENTS:

            male_events = (
                self.MALE_EVENTS[
                    age_group
                ]
            )

        else:

            male_events = (
                self.FULL_EVENT_CATALOGUE
            )

        if age_group in self.FEMALE_EVENTS:

            female_events = (
                self.FEMALE_EVENTS[
                    age_group
                ]
            )

        else:

            female_events = (
                self.FULL_EVENT_CATALOGUE
            )

        for event_name in male_events:

            entries.append((
                event_name,
                "Male",
                self.event_type_for_name(
                    event_name
                )
            ))

        for event_name in female_events:

            entries.append((
                event_name,
                "Female",
                self.event_type_for_name(
                    event_name
                )
            ))

        return entries

    # =========================
    # LOAD RECORDS
    # =========================
    def load_records(self):

        age_group = (
            self.age_combo.currentText()
        )

        if not age_group:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        # Start with the standard catalogue.
        entries = {
            (
                event_name.casefold(),
                gender
            ): (
                event_name,
                gender,
                event_type
            )
            for (
                event_name,
                gender,
                event_type
            ) in self.standard_events_for_age(
                age_group
            )
        }

        # Also include events that have actually
        # existed in the database. This means a
        # custom school event automatically becomes
        # available in the record book.
        cur.execute("""
        SELECT DISTINCT
            event_name,
            gender,
            event_type
        FROM events
        WHERE age_group = ?
        AND gender IN (
            'Male',
            'Female'
        )
        """, (
            age_group,
        ))

        for (
            event_name,
            gender,
            event_type
        ) in cur.fetchall():

            entries[
                (
                    event_name.casefold(),
                    gender
                )
            ] = (
                event_name,
                gender,
                event_type
            )

        # Finally include any historic record whose
        # event is no longer in the current catalogue.
        cur.execute("""
        SELECT
            event_name,
            gender,
            event_type,
            performance,
            record_holder,
            record_year,
            updated_at
        FROM athletics_records
        WHERE age_group = ?
        """, (
            age_group,
        ))

        saved_records = {}

        for row in cur.fetchall():

            event_name = row[0]
            gender = row[1]
            event_type = row[2]

            entries[
                (
                    event_name.casefold(),
                    gender
                )
            ] = (
                event_name,
                gender,
                event_type
            )

            saved_records[
                (
                    event_name.casefold(),
                    gender
                )
            ] = {
                "performance": row[3] or "",
                "holder": row[4] or "",
                "year": row[5] or "",
                "updated": row[6] or ""
            }

        conn.close()

        # Keep events in a familiar athletics order,
        # with Male then Female beside one another.
        event_order = {
            name.casefold(): index
            for index, name in enumerate(
                self.FULL_EVENT_CATALOGUE
            )
        }

        gender_order = {
            "Male": 0,
            "Female": 1
        }

        sorted_entries = sorted(
            entries.values(),
            key=lambda row: (
                event_order.get(
                    row[0].casefold(),
                    9999
                ),
                row[0].casefold(),
                gender_order.get(
                    row[1],
                    9
                )
            )
        )

        self.table.setRowCount(
            len(sorted_entries)
        )

        for table_row, (
            event_name,
            gender,
            event_type
        ) in enumerate(sorted_entries):

            key = (
                event_name.casefold(),
                gender
            )

            saved = saved_records.get(
                key,
                {}
            )

            event_item = QTableWidgetItem(
                event_name
            )
            gender_item = QTableWidgetItem(
                gender
            )
            type_item = QTableWidgetItem(
                event_type
            )
            updated_item = QTableWidgetItem(
                saved.get(
                    "updated",
                    ""
                )
            )

            for item in [
                event_item,
                gender_item,
                type_item,
                updated_item
            ]:

                item.setFlags(
                    item.flags()
                    & ~Qt.ItemIsEditable
                )

            self.table.setItem(
                table_row,
                0,
                event_item
            )
            self.table.setItem(
                table_row,
                1,
                gender_item
            )
            self.table.setItem(
                table_row,
                2,
                type_item
            )
            self.table.setItem(
                table_row,
                3,
                QTableWidgetItem(
                    saved.get(
                        "performance",
                        ""
                    )
                )
            )
            self.table.setItem(
                table_row,
                4,
                QTableWidgetItem(
                    saved.get(
                        "holder",
                        ""
                    )
                )
            )
            self.table.setItem(
                table_row,
                5,
                QTableWidgetItem(
                    saved.get(
                        "year",
                        ""
                    )
                )
            )
            self.table.setItem(
                table_row,
                6,
                updated_item
            )

        self.table.resizeColumnsToContents()

    # =========================
    # SAVE RECORDS
    # =========================
    def save_records(self):

        age_group = (
            self.age_combo.currentText()
        )

        if not age_group:
            return

        records_to_save = []
        records_to_clear = []

        for row in range(
            self.table.rowCount()
        ):

            event_item = self.table.item(
                row,
                0
            )
            gender_item = self.table.item(
                row,
                1
            )
            type_item = self.table.item(
                row,
                2
            )

            if (
                not event_item
                or not gender_item
                or not type_item
            ):
                continue

            event_name = (
                event_item.text().strip()
            )
            gender = (
                gender_item.text().strip()
            )
            event_type = (
                type_item.text().strip()
            )

            performance_item = (
                self.table.item(
                    row,
                    3
                )
            )
            holder_item = self.table.item(
                row,
                4
            )
            year_item = self.table.item(
                row,
                5
            )

            performance = (
                performance_item.text().strip()
                if performance_item
                else ""
            )
            holder = (
                holder_item.text().strip()
                if holder_item
                else ""
            )
            year = (
                year_item.text().strip()
                if year_item
                else ""
            )

            if not performance:

                if holder or year:

                    QMessageBox.warning(
                        self,
                        "Record Value Missing",
                        (
                            f"{event_name} ({gender} {age_group}) "
                            "has a holder or year but no Record value.\n\n"
                            "Enter the record performance, or clear the "
                            "holder/year as well."
                        )
                    )

                    return

                records_to_clear.append((
                    event_name,
                    gender
                ))

                continue

            if year:

                if (
                    len(year) != 4
                    or not year.isdigit()
                ):

                    QMessageBox.warning(
                        self,
                        "Invalid Record Year",
                        (
                            f"{event_name} ({gender} {age_group}) "
                            f"has an invalid year: {year}\n\n"
                            "Use a four-digit year such as 2026, "
                            "or leave the year blank."
                        )
                    )

                    return

            records_to_save.append((
                event_name,
                gender,
                event_type,
                performance,
                holder,
                year
            ))

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        try:

            cur.execute("BEGIN")

            # A completely blank record means that
            # saved record should be cleared. The row
            # still remains visible from the catalogue.
            for (
                event_name,
                gender
            ) in records_to_clear:

                cur.execute("""
                DELETE FROM athletics_records
                WHERE age_group = ?
                AND LOWER(event_name) = LOWER(?)
                AND gender = ?
                """, (
                    age_group,
                    event_name,
                    gender
                ))

            for (
                event_name,
                gender,
                event_type,
                performance,
                holder,
                year
            ) in records_to_save:

                cur.execute("""
                INSERT INTO athletics_records
                (
                    age_group,
                    event_name,
                    gender,
                    event_type,
                    performance,
                    record_holder,
                    record_year,
                    updated_at
                )
                VALUES (
                    ?, ?, ?, ?, ?, ?, ?,
                    CURRENT_TIMESTAMP
                )

                ON CONFLICT(
                    age_group,
                    event_name,
                    gender
                )
                DO UPDATE SET
                    event_type =
                        excluded.event_type,
                    performance =
                        excluded.performance,
                    record_holder =
                        excluded.record_holder,
                    record_year =
                        excluded.record_year,
                    updated_at =
                        CURRENT_TIMESTAMP
                """, (
                    age_group,
                    event_name,
                    gender,
                    event_type,
                    performance,
                    holder,
                    year
                ))

            conn.commit()

        except sqlite3.Error as error:

            conn.rollback()
            conn.close()

            QMessageBox.critical(
                self,
                "Records Not Saved",
                (
                    "The athletics records could not "
                    "be saved.\n\n"
                    f"Database error:\n{error}"
                )
            )

            return

        conn.close()

        self.load_records()

        QMessageBox.information(
            self,
            "Records Saved",
            (
                f"The {age_group} record book "
                "has been saved successfully."
            )
        )


