    def _readonly_item(
        self,
        value
    ):

        item = QTableWidgetItem(
            str(value or "")
        )

        item.setFlags(
            item.flags()
            & ~Qt.ItemIsEditable
        )

        return item


    def load_programme(self):

        meeting_id = get_active_meeting()

        self.table.setRowCount(0)

        if not meeting_id:

            self.status_label.setText(
                "No active meeting selected."
            )

            return

        try:

            rows = sync_programme_schedule(
                meeting_id
            )

        except sqlite3.Error as error:

            QMessageBox.critical(
                self,
                "Programme Error",
                (
                    "AthletiDesk could not load "
                    "the programme editor.\n\n"
                    f"Database error:\n{error}"
                )
            )

            return

        self.table.setRowCount(
            len(rows)
        )

        missing_times = 0
        overridden_times = 0

        for row_index, row in enumerate(
            rows
        ):

            order_item = self._readonly_item(
                row_index + 1
            )

            order_item.setData(
                Qt.UserRole,
                row["item_key"]
            )

            self.table.setItem(
                row_index,
                0,
                order_item
            )

            time_item = QTableWidgetItem(
                row["time"]
            )
            time_item.setTextAlignment(
                Qt.AlignCenter
            )

            self.table.setItem(
                row_index,
                1,
                time_item
            )

            self.table.setItem(
                row_index,
                2,
                self._readonly_item(
                    row["gender_age"]
                )
            )

            self.table.setItem(
                row_index,
                3,
                self._readonly_item(
                    row["event_name"]
                )
            )

            self.table.setItem(
                row_index,
                4,
                self._readonly_item(
                    row["stage"]
                )
            )

            auto_item = self._readonly_item(
                row["auto_time"]
            )
            auto_item.setTextAlignment(
                Qt.AlignCenter
            )

            self.table.setItem(
                row_index,
                5,
                auto_item
            )

            if not _normalise_programme_time(
                row["time"]
            ):
                missing_times += 1

            if row["time_overridden"]:
                overridden_times += 1

        self.table.resizeColumnsToContents()

        self.status_label.setText(
            (
                f"Programme items: {len(rows)}  |  "
                f"Manual time changes: {overridden_times}  |  "
                f"Missing times: {missing_times}"
            )
        )


    def save_programme(
        self,
        show_success=True
    ):

        meeting_id = get_active_meeting()

        if not meeting_id:

            QMessageBox.warning(
                self,
                "No Active Meeting",
                "Select an active meeting first."
            )

            return False

        updates = []

        for row in range(
            self.table.rowCount()
        ):

            key_item = self.table.item(
                row,
                0
            )

            time_item = self.table.item(
                row,
                1
            )

            auto_item = self.table.item(
                row,
                5
            )

            if not key_item:
                continue

            item_key = key_item.data(
                Qt.UserRole
            )

            raw_time = (
                time_item.text().strip()
                if time_item
                else ""
            )

            saved_time = (
                _normalise_programme_time(
                    raw_time
                )
            )

            if not saved_time:

                event_name = (
                    self.table.item(
                        row,
                        3
                    ).text()
                    if self.table.item(
                        row,
                        3
                    )
                    else "Programme item"
                )

                QMessageBox.warning(
                    self,
                    "Invalid Programme Time",
                    (
                        f"Row {row + 1} - {event_name}\n\n"
                        "Enter a time in 24-hour HH:MM "
                        "format, for example 08:30."
                    )
                )

                self.table.setCurrentCell(
                    row,
                    1
                )

                return False

            auto_time = (
                _normalise_programme_time(
                    auto_item.text()
                    if auto_item
                    else ""
                )
            )

            time_overridden = int(
                saved_time != auto_time
            )

            updates.append((
                saved_time,
                time_overridden,
                (row + 1) * 10,
                meeting_id,
                item_key
            ))

            if time_item:
                time_item.setText(
                    saved_time
                )

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        try:

            cur.executemany("""
            UPDATE programme_items
            SET
                scheduled_time = ?,
                time_overridden = ?,
                sort_order = ?
            WHERE meeting_id = ?
            AND item_key = ?
            """, updates)

            conn.commit()

        except sqlite3.Error as error:

            conn.rollback()

            QMessageBox.critical(
                self,
                "Programme Save Failed",
                (
                    "AthletiDesk could not save "
                    "the programme.\n\n"
                    f"Database error:\n{error}"
                )
            )

            return False

        finally:

            conn.close()

        self._renumber_rows()

        manual_count = sum(
            update[1]
            for update in updates
        )

        self.status_label.setText(
            (
                f"Programme saved: {len(updates)} items  |  "
                f"Manual time changes: {manual_count}"
            )
        )

        if show_success:

            QMessageBox.information(
                self,
                "Programme Saved",
                (
                    "The programme order and times "
                    "were saved successfully."
                )
            )

        return True


    def _swap_rows(
        self,
        first_row,
        second_row
    ):

        if (
            first_row < 0
            or second_row < 0
            or first_row >= self.table.rowCount()
            or second_row >= self.table.rowCount()
        ):
            return

        first_items = [
            self.table.takeItem(
                first_row,
                column
            )
            for column in range(
                self.table.columnCount()
            )
        ]

        second_items = [
            self.table.takeItem(
                second_row,
                column
            )
            for column in range(
                self.table.columnCount()
            )
        ]

        for column in range(
            self.table.columnCount()
        ):

            self.table.setItem(
                first_row,
                column,
                second_items[column]
            )

            self.table.setItem(
                second_row,
                column,
                first_items[column]
            )

        self._renumber_rows()


    def _renumber_rows(self):

        for row in range(
            self.table.rowCount()
        ):

            item = self.table.item(
                row,
                0
            )

            if item:
                item.setText(
                    str(row + 1)
                )


    def move_selected_up(self):

        row = self.table.currentRow()

        if row <= 0:
            return

        self._swap_rows(
            row,
            row - 1
        )

        self.table.setCurrentCell(
            row - 1,
            1
        )


    def move_selected_down(self):

        row = self.table.currentRow()

        if (
            row < 0
            or row >= self.table.rowCount() - 1
        ):
            return

        self._swap_rows(
            row,
            row + 1
        )

        self.table.setCurrentCell(
            row + 1,
            1
        )


    def move_selected_to_position(self):

        row = self.table.currentRow()

        if row < 0:

            QMessageBox.warning(
                self,
                "No Programme Item Selected",
                "Select a programme row first."
            )

            return

        row_count = self.table.rowCount()

        new_position, accepted = (
            QInputDialog.getInt(
                self,
                "Move Programme Item",
                "Move selected item to position:",
                row + 1,
                1,
                row_count
            )
        )

        if not accepted:
            return

        target_row = new_position - 1

        while row > target_row:
            self._swap_rows(
                row,
                row - 1
            )
            row -= 1

        while row < target_row:
            self._swap_rows(
                row,
                row + 1
            )
            row += 1

        self.table.setCurrentCell(
            row,
            1
        )


    def reset_selected_time(self):

        row = self.table.currentRow()

        if row < 0:

            QMessageBox.warning(
                self,
                "No Programme Item Selected",
                "Select a programme row first."
            )

            return

        auto_item = self.table.item(
            row,
            5
        )

        time_item = self.table.item(
            row,
            1
        )

        if auto_item and time_item:
            time_item.setText(
                auto_item.text()
            )


    def refresh_and_sync(self):

        # Preserve any unsaved edits before detecting
        # newly generated heats/finals.
        if self.table.rowCount() > 0:

            if not self.save_programme(
                show_success=False
            ):
                return

        self.load_programme()


    def reset_all_to_automatic(self):

        meeting_id = get_active_meeting()

        if not meeting_id:
            return

        answer = QMessageBox.question(
            self,
            "Reset Programme",
            (
                "Reset the full programme to the "
                "automatic event times and automatic "
                "chronological order?\n\n"
                "All manual programme time/order edits "
                "for this meeting will be removed."
            ),
            QMessageBox.Yes
            | QMessageBox.No
        )

        if answer != QMessageBox.Yes:
            return

        conn = sqlite3.connect(DB_NAME)
        cur = conn.cursor()

        try:

            cur.execute("""
            DELETE FROM programme_items
            WHERE meeting_id = ?
            """, (
                meeting_id,
            ))

            conn.commit()

        finally:

            conn.close()

        self.load_programme()


    def save_and_export(self):

        if not self.save_programme(
            show_success=False
        ):
            return

        if self.export_callback:
            self.export_callback()


