def make_dashboard_icon(
    kind,
    color="#0B2E63",
    size=30
):
    """Create small vector-style icons without external assets."""

    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)

    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing)

    pen_width = max(2.0, size / 12.0)
    pen = QPen(
        QColor(color),
        pen_width,
        Qt.SolidLine,
        Qt.RoundCap,
        Qt.RoundJoin
    )
    painter.setPen(pen)
    painter.setBrush(Qt.NoBrush)

    s = float(size)

    def line(x1, y1, x2, y2):
        painter.drawLine(
            QPointF(x1 * s, y1 * s),
            QPointF(x2 * s, y2 * s)
        )

    if kind == "home":
        roof = QPolygonF([
            QPointF(0.16*s, 0.48*s),
            QPointF(0.50*s, 0.18*s),
            QPointF(0.84*s, 0.48*s)
        ])
        painter.drawPolyline(roof)
        painter.drawRect(QRectF(0.27*s, 0.46*s, 0.46*s, 0.36*s))
        painter.drawRect(QRectF(0.45*s, 0.62*s, 0.12*s, 0.20*s))

    elif kind == "calendar":
        painter.drawRoundedRect(
            QRectF(0.14*s, 0.20*s, 0.72*s, 0.64*s),
            0.08*s, 0.08*s
        )
        line(0.14, 0.39, 0.86, 0.39)
        line(0.32, 0.12, 0.32, 0.29)
        line(0.68, 0.12, 0.68, 0.29)
        line(0.50, 0.49, 0.50, 0.72)
        line(0.385, 0.605, 0.615, 0.605)

    elif kind == "folder":
        path = QPolygonF([
            QPointF(0.12*s, 0.30*s),
            QPointF(0.40*s, 0.30*s),
            QPointF(0.48*s, 0.39*s),
            QPointF(0.88*s, 0.39*s),
            QPointF(0.82*s, 0.78*s),
            QPointF(0.12*s, 0.78*s)
        ])
        painter.drawPolygon(path)

    elif kind in {"users", "team"}:
        painter.drawEllipse(QRectF(0.38*s, 0.16*s, 0.24*s, 0.24*s))
        painter.drawEllipse(QRectF(0.10*s, 0.25*s, 0.18*s, 0.18*s))
        painter.drawEllipse(QRectF(0.72*s, 0.25*s, 0.18*s, 0.18*s))
        painter.drawArc(QRectF(0.23*s, 0.38*s, 0.54*s, 0.42*s), 15*16, 150*16)
        painter.drawArc(QRectF(0.02*s, 0.43*s, 0.33*s, 0.33*s), 20*16, 140*16)
        painter.drawArc(QRectF(0.65*s, 0.43*s, 0.33*s, 0.33*s), 20*16, 140*16)

    elif kind == "user":
        painter.drawEllipse(QRectF(0.36*s, 0.14*s, 0.28*s, 0.28*s))
        painter.drawArc(QRectF(0.22*s, 0.39*s, 0.56*s, 0.48*s), 15*16, 150*16)

    elif kind == "runner":
        painter.drawEllipse(QRectF(0.58*s, 0.08*s, 0.16*s, 0.16*s))
        line(0.59, 0.29, 0.46, 0.50)
        line(0.46, 0.50, 0.64, 0.59)
        line(0.48, 0.40, 0.29, 0.35)
        line(0.46, 0.50, 0.30, 0.72)
        line(0.64, 0.59, 0.78, 0.80)
        line(0.52, 0.35, 0.73, 0.39)

    elif kind == "document":
        painter.drawRoundedRect(
            QRectF(0.21*s, 0.12*s, 0.58*s, 0.76*s),
            0.04*s, 0.04*s
        )
        line(0.33, 0.38, 0.67, 0.38)
        line(0.33, 0.52, 0.67, 0.52)
        line(0.33, 0.66, 0.60, 0.66)

    elif kind == "database":
        painter.drawEllipse(QRectF(0.18*s, 0.17*s, 0.64*s, 0.22*s))
        painter.drawArc(QRectF(0.18*s, 0.36*s, 0.64*s, 0.22*s), 180*16, 180*16)
        painter.drawArc(QRectF(0.18*s, 0.56*s, 0.64*s, 0.22*s), 180*16, 180*16)
        line(0.18, 0.28, 0.18, 0.68)
        line(0.82, 0.28, 0.82, 0.68)
        painter.drawArc(QRectF(0.18*s, 0.57*s, 0.64*s, 0.22*s), 0, -180*16)

    elif kind == "chart":
        painter.setBrush(QBrush(QColor(color)))
        painter.drawRoundedRect(QRectF(0.18*s, 0.52*s, 0.13*s, 0.30*s), 2, 2)
        painter.drawRoundedRect(QRectF(0.40*s, 0.34*s, 0.13*s, 0.48*s), 2, 2)
        painter.drawRoundedRect(QRectF(0.62*s, 0.18*s, 0.13*s, 0.64*s), 2, 2)
        painter.setBrush(Qt.NoBrush)

    elif kind == "stopwatch":
        painter.drawEllipse(QRectF(0.19*s, 0.25*s, 0.62*s, 0.62*s))
        line(0.50, 0.09, 0.50, 0.22)
        line(0.41, 0.09, 0.59, 0.09)
        line(0.72, 0.24, 0.80, 0.17)
        line(0.50, 0.56, 0.50, 0.37)
        line(0.50, 0.56, 0.64, 0.63)

    elif kind in {"trophy", "field"}:
        painter.drawRoundedRect(QRectF(0.28*s, 0.18*s, 0.44*s, 0.34*s), 0.06*s, 0.06*s)
        painter.drawArc(QRectF(0.10*s, 0.22*s, 0.26*s, 0.27*s), 75*16, 180*16)
        painter.drawArc(QRectF(0.64*s, 0.22*s, 0.26*s, 0.27*s), -75*16, -180*16)
        line(0.50, 0.52, 0.50, 0.70)
        line(0.36, 0.72, 0.64, 0.72)
        line(0.30, 0.82, 0.70, 0.82)

    elif kind == "calculator":
        painter.drawRoundedRect(QRectF(0.22*s, 0.12*s, 0.56*s, 0.76*s), 0.05*s, 0.05*s)
        painter.drawRect(QRectF(0.32*s, 0.23*s, 0.36*s, 0.16*s))
        for row in range(2):
            for col in range(3):
                painter.drawEllipse(QRectF((0.31+col*0.14)*s, (0.52+row*0.14)*s, 0.07*s, 0.07*s))

    elif kind in {"download", "upload"}:
        if kind == "download":
            line(0.50, 0.17, 0.50, 0.63)
            line(0.35, 0.49, 0.50, 0.64)
            line(0.65, 0.49, 0.50, 0.64)
        else:
            line(0.50, 0.65, 0.50, 0.20)
            line(0.35, 0.35, 0.50, 0.20)
            line(0.65, 0.35, 0.50, 0.20)
        line(0.22, 0.77, 0.78, 0.77)
        line(0.22, 0.77, 0.22, 0.65)
        line(0.78, 0.77, 0.78, 0.65)

    elif kind == "gear":
        painter.drawEllipse(QRectF(0.31*s, 0.31*s, 0.38*s, 0.38*s))
        for i in range(8):
            import math
            a = math.radians(i * 45)
            x1 = 0.50 + 0.24 * math.cos(a)
            y1 = 0.50 + 0.24 * math.sin(a)
            x2 = 0.50 + 0.37 * math.cos(a)
            y2 = 0.50 + 0.37 * math.sin(a)
            line(x1, y1, x2, y2)
        painter.drawEllipse(QRectF(0.43*s, 0.43*s, 0.14*s, 0.14*s))

    elif kind == "pencil":
        pen2 = QPen(QColor(color), max(4.0, size/7.0), Qt.SolidLine, Qt.RoundCap)
        painter.setPen(pen2)
        line(0.25, 0.75, 0.72, 0.28)
        painter.setPen(pen)
        line(0.20, 0.80, 0.31, 0.76)
        line(0.69, 0.25, 0.76, 0.32)

    elif kind == "printer":
        painter.drawRoundedRect(QRectF(0.16*s, 0.34*s, 0.68*s, 0.37*s), 0.05*s, 0.05*s)
        painter.drawRect(QRectF(0.29*s, 0.11*s, 0.42*s, 0.28*s))
        painter.drawRect(QRectF(0.29*s, 0.61*s, 0.42*s, 0.26*s))
        painter.drawEllipse(QRectF(0.69*s, 0.44*s, 0.06*s, 0.06*s))

    elif kind == "pdf":
        painter.drawRoundedRect(QRectF(0.22*s, 0.10*s, 0.56*s, 0.80*s), 0.04*s, 0.04*s)
        font = QFont("Segoe UI", max(7, int(size*0.20)), QFont.Bold)
        painter.setFont(font)
        painter.drawText(QRectF(0.25*s, 0.45*s, 0.50*s, 0.24*s), Qt.AlignCenter, "PDF")

    elif kind == "flag":
        line(0.28, 0.13, 0.28, 0.86)
        flag = QPolygonF([
            QPointF(0.30*s, 0.18*s),
            QPointF(0.74*s, 0.18*s),
            QPointF(0.60*s, 0.38*s),
            QPointF(0.74*s, 0.55*s),
            QPointF(0.30*s, 0.55*s)
        ])
        painter.drawPolyline(flag)

    elif kind == "plus":
        line(0.50, 0.22, 0.50, 0.78)
        line(0.22, 0.50, 0.78, 0.50)

    elif kind == "minus":
        line(0.22, 0.50, 0.78, 0.50)

    elif kind == "refresh":
        painter.drawArc(QRectF(0.19*s, 0.19*s, 0.62*s, 0.62*s), 35*16, 250*16)
        line(0.69, 0.16, 0.82, 0.21)
        line(0.82, 0.21, 0.78, 0.35)

    elif kind == "trash":
        painter.drawRoundedRect(QRectF(0.29*s, 0.31*s, 0.42*s, 0.50*s), 0.04*s, 0.04*s)
        line(0.23, 0.26, 0.77, 0.26)
        line(0.40, 0.18, 0.60, 0.18)
        line(0.43, 0.43, 0.43, 0.69)
        line(0.57, 0.43, 0.57, 0.69)

    else:
        painter.drawEllipse(QRectF(0.24*s, 0.24*s, 0.52*s, 0.52*s))

    painter.end()
    return QIcon(pixmap)


def athletidesk_logo_pixmap(
    max_width=520,
    max_height=115
):
    pixmap = QPixmap()

    try:
        logo_data = base64.b64decode(
            ATHLETIDESK_LOGO_BASE64.encode("ascii")
        )
        pixmap.loadFromData(logo_data, "PNG")
    except Exception:
        return QPixmap()

    if pixmap.isNull():
        return pixmap

    return pixmap.scaled(
        max_width,
        max_height,
        Qt.KeepAspectRatio,
        Qt.SmoothTransformation
    )


