    def _make_section_card(
        self,
        title,
        subtitle,
        color,
        icon_kind,
        items,
        columns=1,
        dark_header=False,
        card_height=390,
        button_height=58,
        button_font_size=14
    ):

        card = QFrame()
        card.setObjectName(
            "sectionCard"
        )
        card.setFixedHeight(
            card_height
        )
        card.setSizePolicy(
            QSizePolicy.Expanding,
            QSizePolicy.Fixed
        )

        card.setStyleSheet("""
            QFrame#sectionCard {
                background: #FFFFFF;
                border: 1px solid #D9E1EC;
                border-radius: 14px;
            }
        """)

        card_layout = QVBoxLayout(
            card
        )
        card_layout.setContentsMargins(
            0,
            0,
            0,
            12
        )
        card_layout.setSpacing(0)

        header = QFrame()
        header.setObjectName(
            "sectionHeader"
        )
        header.setFixedHeight(94)
        header.setSizePolicy(
            QSizePolicy.Expanding,
            QSizePolicy.Fixed
        )

        color_obj = QColor(color)
        lighter = (
            color_obj.lighter(114).name()
        )

        header.setStyleSheet(
            "QFrame#sectionHeader {"
            "background: qlineargradient("
            "x1:0, y1:0, x2:1, y2:0, "
            f"stop:0 {color}, "
            f"stop:1 {lighter});"
            "border-top-left-radius: 14px;"
            "border-top-right-radius: 14px;"
            "}"
        )

        header_layout = QHBoxLayout(
            header
        )
        header_layout.setContentsMargins(
            22,
            12,
            18,
            10
        )
        header_layout.setSpacing(16)

        header_text_color = (
            "#201D05"
            if dark_header
            else "#FFFFFF"
        )

        icon_color = (
            "#201D05"
            if dark_header
            else "#FFFFFF"
        )

        icon_label = QLabel()
        icon_label.setPixmap(
            make_dashboard_icon(
                icon_kind,
                icon_color,
                44
            ).pixmap(
                44,
                44
            )
        )
        icon_label.setFixedSize(
            50,
            50
        )
        icon_label.setAlignment(
            Qt.AlignCenter
        )
        # Keep the icon container fully transparent.
        # The section gradient belongs only to the header frame.
        icon_label.setAutoFillBackground(False)
        icon_label.setStyleSheet(
            "background: transparent;"
            "border: none;"
        )

        # Keep the title and description as one compact text block.
        # Fixed label heights prevent QVBoxLayout from stretching the
        # two labels apart when the coloured header has spare height.
        heading_layout = QVBoxLayout()
        heading_layout.setContentsMargins(
            0,
            0,
            0,
            0
        )
        heading_layout.setSpacing(1)
        heading_layout.setAlignment(
            Qt.AlignVCenter
        )

        heading = QLabel(title)
        heading.setFixedHeight(28)
        heading.setSizePolicy(
            QSizePolicy.Expanding,
            QSizePolicy.Fixed
        )
        heading.setAlignment(
            Qt.AlignLeft | Qt.AlignVCenter
        )
        heading.setStyleSheet(
            f"color: {header_text_color};"
            "font-size: 21px;"
            "font-weight: 800;"
            "margin: 0px;"
            "padding: 0px;"
        )

        subheading = QLabel(
            subtitle
        )
        subheading.setWordWrap(False)
        subheading.setFixedHeight(18)
        subheading.setSizePolicy(
            QSizePolicy.Expanding,
            QSizePolicy.Fixed
        )
        subheading.setAlignment(
            Qt.AlignLeft | Qt.AlignVCenter
        )
        subheading.setStyleSheet(
            f"color: {header_text_color};"
            "font-size: 12px;"
            "font-weight: 500;"
            "margin: 0px;"
            "padding: 0px;"
        )

        heading_layout.addWidget(
            heading
        )
        heading_layout.addWidget(
            subheading
        )

        header_layout.addWidget(
            icon_label
        )
        header_layout.addLayout(
            heading_layout,
            1
        )

        card_layout.addWidget(
            header
        )

        body = QWidget()
        body.setSizePolicy(
            QSizePolicy.Expanding,
            QSizePolicy.Fixed
        )

        body_layout = QGridLayout(
            body
        )
        body_layout.setContentsMargins(
            16,
            14,
            16,
            0
        )
        body_layout.setHorizontalSpacing(
            10
        )
        body_layout.setVerticalSpacing(
            10
        )
        body_layout.setAlignment(
            Qt.AlignTop
        )

        for index, item in enumerate(
            items
        ):

            (
                label,
                callback,
                item_icon
            ) = item

            button = (
                self._make_dashboard_button(
                    label,
                    callback,
                    item_icon,
                    color,
                    button_height=button_height,
                    font_size=button_font_size
                )
            )

            row = (
                index
                // columns
            )
            column = (
                index
                % columns
            )

            body_layout.addWidget(
                button,
                row,
                column
            )

        for column in range(
            columns
        ):

            body_layout.setColumnStretch(
                column,
                1
            )

        card_layout.addWidget(
            body,
            0,
            Qt.AlignTop
        )
        card_layout.addStretch(1)

        return card

    def _make_dashboard_button(
        self,
        text,
        callback,
        icon_kind,
        accent_color,
        button_height=58,
        font_size=14
    ):

        button = QPushButton()
        button.setFixedHeight(
            button_height
        )
        button.setCursor(
            Qt.PointingHandCursor
        )
        button.clicked.connect(
            callback
        )

        button.setStyleSheet(
            "QPushButton {"
            "background: #FBFCFE;"
            "border: 1px solid #D7E0EB;"
            "border-radius: 10px;"
            "text-align: left;"
            "}"
            "QPushButton:hover {"
            "background: #F5F8FC;"
            f"border: 1px solid {accent_color};"
            "}"
            "QPushButton:pressed {"
            "background: #ECF2F8;"
            "}"
        )

        button_layout = QHBoxLayout(
            button
        )
        button_layout.setContentsMargins(
            14,
            5,
            10,
            5
        )
        button_layout.setSpacing(
            11
        )

        icon = QLabel()
        icon_size = (
            27
            if button_height >= 54
            else 24
        )
        icon.setPixmap(
            make_dashboard_icon(
                icon_kind,
                "#0B2E63",
                icon_size
            ).pixmap(
                icon_size,
                icon_size
            )
        )
        icon.setFixedSize(
            icon_size + 2,
            icon_size + 2
        )
        icon.setAttribute(
            Qt.WA_TransparentForMouseEvents,
            True
        )

        label = QLabel(
            text
        )
        label.setStyleSheet(
            "color: #0B2E63;"
            f"font-size: {font_size}px;"
            "font-weight: 600;"
        )
        label.setWordWrap(
            True
        )
        label.setAlignment(
            Qt.AlignVCenter
            | Qt.AlignLeft
        )
        label.setAttribute(
            Qt.WA_TransparentForMouseEvents,
            True
        )

        arrow = QLabel("›")
        arrow.setStyleSheet(
            "color: #6D7E99;"
            "font-size: 21px;"
            "font-weight: 400;"
        )
        arrow.setFixedWidth(12)
        arrow.setAlignment(
            Qt.AlignCenter
        )
        arrow.setAttribute(
            Qt.WA_TransparentForMouseEvents,
            True
        )

        button_layout.addWidget(
            icon
        )
        button_layout.addWidget(
            label,
            1
        )
        button_layout.addWidget(
            arrow
        )

        return button

